window.MULTI5B={"bok":"Multi 5b Grunnbok (Gyldendal)","trinn":"5. trinn","oppgaver":[{"id":"M5B-5.1","bok":"5.1","side":"4-5","kap":5,"tema":"Geometri og måling","emne":"Vi måler lengder","type":"Tekstoppgave","niva":2,"figur":true,"ferdighet":"Finne omkrets av en tomt og multiplisere med pris/antall per meter","q":"Sara skal sette opp gjerde rundt en rektangulær tomt som er 12 m lang og 8 m bred. Hun trenger 4 stolper per meter gjerde. Hvor mange stolper må hun kjøpe?","a":"Omkrets 40 m. 40 · 4 = 160 stolper","ekstra":[]},{"id":"M5B-5.2","bok":"5.2 a-b","side":"4-5","kap":5,"tema":"Geometri og måling","emne":"Vi måler lengder","type":"Tekstoppgave","niva":2,"figur":true,"ferdighet":"Bruke areal og forbruk per enhet; deling med rest/avrunding opp","q":"a) 1 liter maling dekker 6 m². Veggen er 30 m². Hvor mange liter trenger du? b) 1 pakke gressfrø dekker 25 m². Plenen er 150 m². Hvor mange pakker trenger du?","a":"a) 30 : 6 = 5 liter. b) 150 : 25 = 6 pakker","ekstra":[]},{"id":"M5B-5.3","bok":"5.3 a-b","side":"4-5","kap":5,"tema":"Geometri og måling","emne":"Vi måler lengder","type":"Tekstoppgave","niva":3,"figur":true,"ferdighet":"Finne hvor mange fliser som går på 1 m² og på et større område","q":"Fliser er 25 cm · 25 cm. a) Hvor mange fliser går det på 1 m²? b) Hvor mange fliser trenger du til en terrasse på 9 m²?","a":"a) 4 · 4 = 16 fliser. b) 9 · 16 = 144 fliser","ekstra":[]},{"id":"M5B-5.4","bok":"5.4 a-f","side":"6-7","kap":5,"tema":"Geometri og måling","emne":"Vi måler lengder","type":"Visuell oppgave","niva":1,"figur":true,"ferdighet":"Velge passende målenhet for ulike gjenstander og avstander","q":"Hvilken målenhet (mm, cm, m eller km) passer best når vi skal måle: a) lengden av en tannbørste, b) høyden på en flaggstang, c) tykkelsen på en mynt, d) avstanden fra skolen til nærmeste by?","a":"a) cm. b) m. c) mm. d) km","ekstra":[]},{"id":"M5B-5.5","bok":"5.5 a-f","side":"6-7","kap":5,"tema":"Geometri og måling","emne":"Vi måler lengder","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Sette riktig enhet (mm, cm, m, km) bak et tall i en konkret situasjon","q":"Skriv mm, cm, m eller km bak tallene slik at de beskriver riktig lengde. a) Høyden på en dør er 2. b) Lengden av en maur er 4. c) Avstanden mellom Oslo og Trondheim er ca. 500. d) Lengden av en sko er 28. e) Bredden på et klasserom er 7. f) Tykkelsen på en ledning er 3.","a":"a) m. b) mm. c) km. d) cm. e) m. f) mm","ekstra":[]},{"id":"M5B-5.6","bok":"5.6","side":"6-7","kap":5,"tema":"Geometri og måling","emne":"Vi måler lengder","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Måle linjestykker nøyaktig og oppgi svaret både i mm og i cm (desimaltall)","q":"Mål lengden av linjestykkene. Oppgi både i millimeter og centimeter. Eksempel: AB = 11 mm = 1,1 cm.","a":"Appen tegner linjestykker med kjent lengde (f.eks. 34, 58, 72 og 95 mm = 3,4; 5,8; 7,2 og 9,5 cm). Utskrift må være 100 % skala.","ekstra":[]},{"id":"M5B-5.7","bok":"5.7 a-e","side":"6-7","kap":5,"tema":"Geometri og måling","emne":"Vi måler lengder","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Gjøre om cm til mm (gange med 10, også desimaltall)","q":"Skriv som millimeter. a) 3,2 cm b) 5,8 cm c) 12 cm d) 6,7 cm e) 20 cm","a":"a) 32 mm. b) 58 mm. c) 120 mm. d) 67 mm. e) 200 mm","ekstra":[]},{"id":"M5B-5.8","bok":"5.8 a-e","side":"6-7","kap":5,"tema":"Geometri og måling","emne":"Vi måler lengder","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Gjøre om mm og dm til cm","q":"Skriv som centimeter. a) 24 mm b) 35 mm c) 70 mm d) 2 dm e) 3,5 dm","a":"a) 2,4 cm. b) 3,5 cm. c) 7 cm. d) 20 cm. e) 35 cm","ekstra":[]},{"id":"M5B-5.9","bok":"5.9","side":"8","kap":5,"tema":"Geometri og måling","emne":"Vi måler lengder","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Tegne linjestykker med oppgitt lengde og skrive lengden både i cm og mm","q":"Tegn linjestykkene og skriv målene både i cm og mm. AB = 34 mm, CD = 7,5 cm, EF = 62 mm, GH = 1,2 cm.","a":"AB = 34 mm = 3,4 cm. CD = 7,5 cm = 75 mm. EF = 62 mm = 6,2 cm. GH = 1,2 cm = 12 mm","ekstra":[]},{"id":"M5B-5.10","bok":"5.10 a-b","side":"8","kap":5,"tema":"Geometri og måling","emne":"Vi måler lengder","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Måle ting med linjal og fylle ut tabell med mm, cm og dm; velge selv tre ting","q":"a) En blyant er 150 mm lang. Fyll ut: ___ mm = ___ cm = ___ dm. b) Et viskelær er 45 mm. Skriv lengden i cm og dm.","a":"a) 150 mm = 15 cm = 1,5 dm. b) 45 mm = 4,5 cm = 0,45 dm","ekstra":[]},{"id":"M5B-5.11","bok":"5.11","side":"9","kap":5,"tema":"Geometri og måling","emne":"Vi måler lengder","type":"Åpen utforsking","niva":2,"figur":true,"ferdighet":"Måle lengden av en kurve ved å legge en snor langs den og måle snoren","q":"Kurve P måles med en snor, og snora blir 28 cm når den rettes ut. Kurve Q blir 19 cm. Hvor lange er kurvene til sammen, og hvor mye lengre er P enn Q?","a":"Til sammen 28 + 19 = 47 cm. Forskjell 28 − 19 = 9 cm","ekstra":[]},{"id":"M5B-5.12","bok":"5.12 a-b","side":"9","kap":5,"tema":"Geometri og måling","emne":"Vi måler lengder","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Måle ulike ting og oppgi målene i cm, dm og m i tabell; velge selv tre ting","q":"a) Et skrivebord er 120 cm langt. Fyll ut: ___ cm = ___ dm = ___ m. b) En dør er 2 m høy. Oppgi høyden i dm og cm.","a":"a) 120 cm = 12 dm = 1,2 m. b) 2 m = 20 dm = 200 cm","ekstra":[]},{"id":"M5B-5.13","bok":"5.13","side":"10","kap":5,"tema":"Geometri og måling","emne":"Omkrets","type":"Tekstoppgave","niva":2,"figur":true,"ferdighet":"Finne hvor langt gjerde som trengs rundt en innhegning (omkrets) ut fra et bilde med målestokk 1 cm → 1 m","q":"Mia skal lage en rektangulær innhegning til hønsene sine. Den skal være 5 m lang og 3 m bred. Hvor langt gjerde trenger hun?","a":"5 + 3 + 5 + 3 = 16 m","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.14","bok":"5.14 a-d","side":"10","kap":5,"tema":"Geometri og måling","emne":"Omkrets","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Finne omkretsen av områder ut fra tegning der 1 cm → 1 m","q":"Finn omkretsen. a) Kvadrat med side 4 m. b) Rektangel 6 m · 2 m. c) Trekant med sidene 3 m, 4 m og 5 m. d) Firkant med sidene 5 m, 4 m, 6 m og 3 m.","a":"a) 4 · 4 = 16 m. b) 6 + 2 + 6 + 2 = 16 m. c) 3 + 4 + 5 = 12 m. d) 5 + 4 + 6 + 3 = 18 m","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.15","bok":"5.15 a-b","side":"11","kap":5,"tema":"Geometri og måling","emne":"Omkrets","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Finne omkretsen av figurer med rette kanter på prikkark ved å telle prikkavstander","q":"a) En L-figur er 3 prikkavstander bred og 4 høy (ytre mål). Hva er omkretsen? b) Et rektangel på 5 · 4 har et hjørne på 2 · 2 klippet bort. Hva er omkretsen?","a":"a) 3 + 4 + 3 + 4 = 14. b) Omkretsen blir den samme som for hele rektangelet: 5 + 4 + 5 + 4 = 18","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.16","bok":"5.16 a-c","side":"11","kap":5,"tema":"Geometri og måling","emne":"Omkrets","type":"Åpen utforsking","niva":3,"figur":false,"ferdighet":"Lage forskjellige figurer med gitt omkrets (8, 12 og selvvalgt) på prikkark","q":"Tegn figurer på prikkark (1 = én prikkavstand). a) Tegn to ulike rektangler med omkrets 10. b) Tegn tre ulike rektangler med omkrets 14.","a":"a) 4 · 1 og 3 · 2 (4+1+4+1 = 10; 3+2+3+2 = 10). b) 6 · 1, 5 · 2 og 4 · 3 (alle har lengde + bredde = 7, omkrets 14)","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.17","bok":"5.17","side":"12","kap":5,"tema":"Geometri og måling","emne":"Omkrets","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Måle sidene i figurer (A-F) med linjal og legge dem sammen til omkrets","q":"Mål sidene med linjal og finn omkretsen. a) En regulær femkant har fem sider på 4,2 cm. b) En trekant har sidene 6,5 cm, 7,5 cm og 5 cm.","a":"a) 5 · 4,2 = 21 cm. b) 6,5 + 7,5 + 5 = 19 cm","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.18","bok":"5.18 a-g","side":"13","kap":5,"tema":"Geometri og måling","emne":"Omkrets","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Finne manglende tall (en side eller omkrets) i tabell for trekanter, med blandede enheter","q":"Finn tallet som mangler for en trekant. a) Sidene 7 cm, 8 cm, 9 cm. Omkrets? b) Sidene 9 cm, 12 cm og ? Omkrets 30 cm. c) Sidene 12 m, ?, 15 m. Omkrets 40 m.","a":"a) 7 + 8 + 9 = 24 cm. b) 30 − 21 = 9 cm. c) 40 − 27 = 13 m","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.19","bok":"5.19 a-g","side":"13","kap":5,"tema":"Geometri og måling","emne":"Omkrets","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Finne manglende tall (en side eller omkrets) i tabell for firkanter, med blandede enheter og desimaltall","q":"Finn tallet som mangler for en firkant. a) Sidene 6 cm, 7 cm, 8 cm, 9 cm. Omkrets? b) Sidene 20 mm, 30 mm, 25 mm og ? Omkrets 100 mm. c) Rektangel 14 dm · 9 dm. Omkrets? d) Sidene 4,5 cm, 3,5 cm, 6 cm, 5 cm. Omkrets?","a":"a) 6 + 7 + 8 + 9 = 30 cm. b) 100 − 75 = 25 mm. c) 14 + 9 + 14 + 9 = 46 dm. d) 4,5 + 3,5 + 6 + 5 = 19 cm","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.20","bok":"5.20 a-b","side":"13","kap":5,"tema":"Geometri og måling","emne":"Omkrets","type":"Åpen utforsking","niva":2,"figur":false,"ferdighet":"Gjette omkrets, måle nøyaktig og finne forskjellen; fylle ut tabell med ting (omkrets ca. 10 cm og > 50 cm)","q":"Velg tre ting (f.eks. mobil, bok, pult). Gjett omkretsen, mål den, og finn forskjellen. Lag tabell: Ting | Gjettet | Målt | Forskjell. Eksempel: gjettet 40 cm, målt 38,5 cm.","a":"Forskjell = større tall − mindre tall. Eksempel: 40 − 38,5 = 1,5 cm. Svar varierer med gjenstander","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.21","bok":"5.21 a-b","side":"14","kap":5,"tema":"Geometri og måling","emne":"Areal","type":"Visuell oppgave","niva":1,"figur":true,"ferdighet":"Telle ruter for å finne areal av fire hus og rangere husene etter størrelse","q":"Hus P dekker 4 · 3 ruter, hus Q 5 · 2 ruter, hus R en 4 · 3-figur der et hjørne på 2 · 2 er tatt bort, og hus S 3 · 3 ruter. a) Hvor mange ruter dekker hvert hus? b) Skriv husene i rekkefølge fra minst til størst.","a":"a) P = 12, Q = 10, R = 12 − 4 = 8, S = 9. b) R (8), S (9), Q (10), P (12)","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.22","bok":"5.22 a-b","side":"14","kap":5,"tema":"Geometri og måling","emne":"Areal","type":"Åpen utforsking","niva":2,"figur":true,"ferdighet":"Dele et område i like store deler, tegne skillelinjer og telle ruter per del","q":"Tre naboer skal dele et uteområde på 6 · 8 ruter likt. a) Tegn skillelinjer. b) Hvor mange ruter får hver?","a":"a) For eksempel tre striper på 2 · 8 ruter. b) 48 : 3 = 16 ruter hver","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.23","bok":"5.23","side":"14","kap":5,"tema":"Geometri og måling","emne":"Areal","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Måle omkretsen til hver eiendom med linjal og oppgi svaret i cm","q":"På et kart er en eiendom et rektangel som er 4,5 cm · 3 cm. Hva er omkretsen i cm?","a":"4,5 + 3 + 4,5 + 3 = 15 cm","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.24","bok":"5.24 a-f","side":"15","kap":5,"tema":"Geometri og måling","emne":"Areal","type":"Tekstoppgave","niva":2,"figur":true,"ferdighet":"Finne areal i m² når hver rute er 10 m² (kaningård, hus, garasje, basseng, plen, trampoline)","q":"På en tomtetegning er hver rute 5 m². a) Et hus dekker 12 ruter. b) En garasje dekker 4 ruter. c) En plen dekker 18 ruter. d) Et basseng dekker 6 ruter. Hvor mange m² er hver?","a":"a) 12 · 5 = 60 m². b) 4 · 5 = 20 m². c) 18 · 5 = 90 m². d) 6 · 5 = 30 m²","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.25","bok":"5.25 a-f","side":"16","kap":5,"tema":"Geometri og måling","emne":"Areal","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Finne arealet av figurer på prikkark, også med halve ruter","q":"Hva er arealet (prikkavstand 1)? a) Rektangel 3 · 2. b) L-figur av 5 ruter. c) Rettvinklet trekant med kateter 4 og 3. d) Trekant som er halvparten av et kvadrat på 2 · 2.","a":"a) 6. b) 5. c) 4 · 3 : 2 = 6. d) 4 : 2 = 2","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.26","bok":"5.26 a-b","side":"16","kap":5,"tema":"Geometri og måling","emne":"Areal","type":"Åpen utforsking","niva":3,"figur":false,"ferdighet":"Tegne ulike figurer med gitt areal og sammenligne med andre","q":"Tegn forskjellige figurer på rutepapir. a) Tre figurer med areal 6. b) To figurer med areal 8.","a":"a) For eksempel rektangel 3 · 2, rektangel 6 · 1 og en L-figur av 6 ruter. b) For eksempel 4 · 2 og 8 · 1","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.27","bok":"5.27 a-f","side":"17","kap":5,"tema":"Geometri og måling","emne":"Areal","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Telle cm²-ruter, også i figurer med halve ruter og trekanter","q":"Hvor mange cm² er figurene? a) Rektangel 4 · 3 ruter. b) Trappefigur med rader på 1, 2, 3 og 4 ruter. c) Rettvinklet trekant med grunnlinje 6 og høyde 4 ruter. d) Rektangler 5 · 2 og 3 · 2 satt sammen.","a":"a) 12 cm². b) 1 + 2 + 3 + 4 = 10 cm². c) 6 · 4 : 2 = 12 cm². d) 10 + 6 = 16 cm²","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.28","bok":"5.28 a-f","side":"18","kap":5,"tema":"Geometri og måling","emne":"Areal","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Finne areal av rektangel ved å multiplisere lengde og bredde ut fra tegnede mål","q":"Hvor mange cm² er rektanglene? a) 7 cm · 4 cm. b) 9 cm · 3 cm. c) 6 cm · 6 cm. d) 8 cm · 5 cm.","a":"a) 28 cm². b) 27 cm². c) 36 cm². d) 40 cm²","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.29","bok":"5.29 a-f","side":"19","kap":5,"tema":"Geometri og måling","emne":"Areal","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Tegne ferdig rektangler på rutenett når areal og én side er gitt (finne manglende side)","q":"Tegn rektanglene. a) A = 20 cm², én side 4 cm. b) A = 18 cm², én side 3 cm. c) A = 36 cm², én side 9 cm. d) A = 35 cm², én side 7 cm.","a":"a) 5 cm. b) 6 cm. c) 4 cm. d) 5 cm (andre side)","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.30","bok":"5.30 a-c","side":"19","kap":5,"tema":"Geometri og måling","emne":"Areal","type":"Åpen utforsking","niva":3,"figur":false,"ferdighet":"Tegne rektangler med gitte areal (flere arealer per delspørsmål)","q":"Tegn rektangler med areal a) 16 cm². b) 30 cm². Finn flest mulig med hele cm.","a":"a) 4 · 4, 2 · 8 og 1 · 16. b) 5 · 6, 3 · 10, 2 · 15 og 1 · 30","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.31","bok":"5.31 a-b","side":"20","kap":5,"tema":"Geometri og måling","emne":"Areal","type":"Åpen utforsking","niva":3,"figur":false,"ferdighet":"Finne alle rektangler med hele cm-sider som har gitt areal (24 og 40 cm²)","q":"Hvor mange forskjellige rektangler med hele cm-sider har areal a) 18 cm²? b) 32 cm²?","a":"a) 1 · 18, 2 · 9, 3 · 6: 3 rektangler. b) 1 · 32, 2 · 16, 4 · 8: 3 rektangler","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.32","bok":"5.32 a-b","side":"20","kap":5,"tema":"Geometri og måling","emne":"Areal","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Finne arealet av et rutenettskvadrat og av en grønn trekant som er halve kvadratet","q":"Et kvadrat har side 6 cm. a) Hva er arealet av kvadratet? b) En trekant dekker halve kvadratet. Hva er arealet av trekanten?","a":"a) 6 · 6 = 36 cm². b) 36 : 2 = 18 cm²","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.33","bok":"5.33 a-b","side":"20","kap":5,"tema":"Geometri og måling","emne":"Areal","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Finne arealet av et rektangel og av trekanter som er halvparten av rektangelet","q":"Et rektangel er 8 cm · 5 cm. a) Hva er arealet av rektangelet? b) En grønn trekant er halvparten av rektangelet. Hva er arealet?","a":"a) 8 · 5 = 40 cm². b) 40 : 2 = 20 cm²","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.34","bok":"5.34 a-c","side":"20","kap":5,"tema":"Geometri og måling","emne":"Areal","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Regne ut areal av røde trekanter som er halvparten av rektangler med oppgitte sider","q":"Regn ut arealet av de røde trekantene. Hver trekant er halve rektangelet. a) 6 cm · 4 cm. b) 3 cm · 9 cm. c) 7 cm · 7 cm.","a":"a) 24 : 2 = 12 cm². b) 27 : 2 = 13,5 cm². c) 49 : 2 = 24,5 cm²","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.35","bok":"5.35","side":"21","kap":5,"tema":"Geometri og måling","emne":"Areal","type":"Forklar og begrunn","niva":3,"figur":true,"ferdighet":"Sammenligne arealet av to trekanter ved å dele dem opp og sette sammen til rektangler","q":"Trekant P har grunnlinje 10 cm og høyde 6 cm. Trekant Q har grunnlinje 12 cm og høyde 5 cm. Hvilken har størst areal? Forklar.","a":"P: 10 · 6 : 2 = 30 cm². Q: 12 · 5 : 2 = 30 cm². Begge like store (30 cm²)","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.36","bok":"5.36 a-d","side":"21","kap":5,"tema":"Geometri og måling","emne":"Areal","type":"Ferdighetstrening","niva":3,"figur":true,"ferdighet":"Regne ut arealet av trekanter ved å bruke grunnlinje og høyde (halve rektangelet)","q":"Regn ut arealet av trekantene (grunnlinje · høyde : 2). a) 8 cm og 5 cm. b) 12 cm og 6 cm. c) 7 cm og 4 cm. d) 9 cm og 8 cm.","a":"a) 40 : 2 = 20 cm². b) 72 : 2 = 36 cm². c) 28 : 2 = 14 cm². d) 72 : 2 = 36 cm²","ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"M5B-5.37","bok":"5.37","side":"22","kap":5,"tema":"Geometri og måling","emne":"Målestokk","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Forstørre en figur på rutenett slik at alle sider blir dobbelt så lange","q":"Forstørr i målestokk 2 : 1. a) Rektangel 3 cm · 2 cm. b) Kvadrat med side 4 cm.","a":"a) 6 cm · 4 cm. b) Kvadrat med side 8 cm","ekstra":[]},{"id":"M5B-5.38","bok":"5.38","side":"23","kap":5,"tema":"Geometri og måling","emne":"Målestokk","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Forminske en figur på rutenett slik at alle sider blir halvparten så lange","q":"Forminsk i målestokk 1 : 2. a) Rektangel 8 cm · 6 cm. b) Kvadrat med side 10 cm.","a":"a) 4 cm · 3 cm. b) Kvadrat med side 5 cm","ekstra":[]},{"id":"M5B-5.39","bok":"5.39 a-d","side":"24","kap":5,"tema":"Geometri og måling","emne":"Målestokk","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Måle avstander på kart med linjal og regne om til virkelighet (1 cm → 10 m)","q":"Kartet har målestokk 1 : 1000. Hvor langt er det i virkeligheten når avstanden på kartet er a) 3 cm? b) 7,5 cm? c) 12 cm? d) 8,2 cm?","a":"a) 30 m. b) 75 m. c) 120 m. d) 82 m","ekstra":[]},{"id":"M5B-5.40","bok":"5.40","side":"24","kap":5,"tema":"Geometri og måling","emne":"Målestokk","type":"Tekstoppgave","niva":3,"figur":true,"ferdighet":"Finne total gangavstand innom alle aktivitetene ved å måle og regne om fra kart","q":"Du går innom fire stopp på et kart med målestokk 1 : 1000. Avstandene på kartet er 3 cm, 4 cm og 2,5 cm. Hvor langt går du?","a":"3 + 4 + 2,5 = 9,5 cm på kartet. 9,5 · 10 = 95 m","ekstra":[]},{"id":"M5B-5.41","bok":"5.41 a-b","side":"25","kap":5,"tema":"Geometri og måling","emne":"Målestokk","type":"Tekstoppgave","niva":3,"figur":true,"ferdighet":"Finne omkretsen til gårder på kart i målestokk 1 : 50 000 og fordele gjerdekostnad der bøndene deler grense","q":"Kart i målestokk 1 : 50 000. Gård X er et rektangel på 4 cm · 2 cm. a) Hvor lang er omkretsen i km? b) X og nabogård Y har felles grense på 4 cm på kartet. De kjøper halve grensen hver. Hvor mange km gjerde må X kjøpe?","a":"a) 2 · (4 + 2) = 12 cm. 12 · 500 = 6000 m = 6 km. b) 4 cm = 2000 m = 2 km. X: 6 − 2 + 1 = 5 km","ekstra":[]},{"id":"M5B-5.42","bok":"5.42","side":"26","kap":5,"tema":"Geometri og måling","emne":"Målestokk","type":"Visuell oppgave","niva":3,"figur":true,"ferdighet":"Tegne figurer (A-D) i riktig størrelse når de er tegnet i målestokk 1 : 5","q":"Figurene er tegnet i målestokk 1 : 5. Hvilke mål har de i virkeligheten? a) Rektangel 2 cm · 1 cm. b) Kvadrat med side 3 cm.","a":"a) 10 cm · 5 cm. b) 15 cm · 15 cm","ekstra":[]},{"id":"M5B-5.43","bok":"5.43","side":"26","kap":5,"tema":"Geometri og måling","emne":"Målestokk","type":"Åpen utforsking","niva":3,"figur":false,"ferdighet":"Lage kart over klasserommet i målestokk 1 : 100 (1 cm tilsvarer 100 cm)","q":"Lag et kart over rommet ditt i målestokk 1 : 100. Rommet er 8 m · 6 m. Hvor store er tegningene på papiret?","a":"8 m = 800 cm -> 8 cm. 6 m = 600 cm -> 6 cm. Tegningen blir 8 cm · 6 cm","ekstra":[]},{"id":"M5B-P1","bok":"Prøve 1","side":"28","kap":5,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 5)","type":"Ferdighetstrening","niva":1,"figur":true,"ferdighet":"Måle lengder (spiker) i mm og cm","q":"En skrue er 45 mm lang. Skriv lengden i cm. En annen skrue er 3,2 cm. Skriv lengden i mm.","a":"4,5 cm. 32 mm","ekstra":[]},{"id":"M5B-P2","bok":"Prøve 2","side":"28","kap":5,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 5)","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Tegne linjestykker og skrive målene i både cm og mm","q":"Skriv målene både i cm og mm: AB = 3,6 cm, CD = 85 mm, EF = 12,4 cm.","a":"AB = 3,6 cm = 36 mm. CD = 8,5 cm = 85 mm. EF = 12,4 cm = 124 mm","ekstra":[]},{"id":"M5B-P3","bok":"Prøve 3 a-d","side":"28","kap":5,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 5)","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Regne om dm til cm","q":"Hvor mange cm er a) 4 dm? b) 2,5 dm? c) 6,7 dm? d) 12 dm?","a":"a) 40 cm. b) 25 cm. c) 67 cm. d) 120 cm","ekstra":[]},{"id":"M5B-P4","bok":"Prøve 4","side":"28","kap":5,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 5)","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Måle sidene i en firkant og en trekant og finne omkretsen","q":"Hva er omkretsen av a) en firkant med sidene 5 cm, 4 cm, 6 cm og 3,5 cm? b) en trekant med sidene 7 cm, 7 cm og 4 cm?","a":"a) 18,5 cm. b) 18 cm","ekstra":[]},{"id":"M5B-P5","bok":"Prøve 5 a-d","side":"29","kap":5,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 5)","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Finne arealet av et rutenett, to kvadrater/rektangler og en trekant","q":"Hva er arealet? a) Rektangel med 4 rader av 6 ruter. b) Kvadrat med side 7 cm. c) Rektangel 9 cm · 4 cm. d) Trekant med grunnlinje 10 cm og høyde 6 cm.","a":"a) 24. b) 49 cm². c) 36 cm². d) 10 · 6 : 2 = 30 cm²","ekstra":[]},{"id":"M5B-P6","bok":"Prøve 6","side":"29","kap":5,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 5)","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Tegne en blyant i riktig størrelse når den er forstørret 2 : 1","q":"Et insekt er tegnet i målestokk 2 : 1 og er 8 cm langt på tegningen. Hvor langt er insektet i virkeligheten?","a":"8 : 2 = 4 cm","ekstra":[]},{"id":"M5B-P7","bok":"Prøve 7","side":"29","kap":5,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 5)","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Tegne en bilderamme i riktig størrelse når den er forminsket 1 : 5","q":"En ramme er tegnet i målestokk 1 : 5 og er 3 cm · 2 cm på tegningen. Hvor stor er den i virkeligheten?","a":"15 cm · 10 cm","ekstra":[]},{"id":"M5B-5.44","bok":"5.44","side":"30","kap":5,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 5)","type":"Tolk data","niva":1,"figur":true,"ferdighet":"Måle sneglespor (A-D) med linjal og oppgi i mm og cm","q":"En snegl har krøpet 7,3 cm. Oppgi lengden i mm. En annen har krøpet 95 mm. Oppgi lengden i cm.","a":"73 mm. 9,5 cm","ekstra":[]},{"id":"M5B-5.45","bok":"5.45 a-b","side":"30","kap":5,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 5)","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Skrive høyder oppgitt i meter som cm og dm","q":"Mia er 1,35 m og Jon er 1,62 m. Skriv høydene a) i cm b) i dm.","a":"a) 135 cm og 162 cm. b) 13,5 dm og 16,2 dm","ekstra":[]},{"id":"M5B-5.46","bok":"5.46 a-c","side":"30","kap":5,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 5)","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Tegne linjestykker med lengde oppgitt i mm","q":"Tegn linjestykkene. a) AB = 35 mm. b) CD = 60 mm. c) EF = 88 mm.","a":"a) 3,5 cm. b) 6 cm. c) 8,8 cm","ekstra":[]},{"id":"M5B-5.47","bok":"5.47 a-c","side":"30","kap":5,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 5)","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Tegne linjestykker med lengde oppgitt i cm (heltall og desimaltall)","q":"Tegn linjestykkene. a) AB = 15 cm. b) CD = 8,5 cm. c) EF = 11,2 cm.","a":"a) 15 cm. b) 8,5 cm = 85 mm. c) 11,2 cm = 112 mm","ekstra":[]},{"id":"M5B-5.48","bok":"5.48 a-c","side":"30","kap":5,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 5)","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Tegne linjestykker med lengde oppgitt i dm","q":"Tegn linjestykkene. a) AB = 1 dm. b) CD = 2,5 dm. c) EF = 1,8 dm.","a":"a) 10 cm. b) 25 cm. c) 18 cm","ekstra":[]},{"id":"M5B-5.49","bok":"5.49","side":"31","kap":5,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 5)","type":"Tolk data","niva":3,"figur":true,"ferdighet":"Måle sidene i figurene A-D og fylle ut tabell med lengde, bredde, omkrets og areal","q":"Fyll ut tabellen. A: rektangel 9 cm · 4 cm. B: kvadrat med side 5 cm. C: rektangel 12 cm · 3 cm. Finn lengde, bredde, omkrets og areal.","a":"A: omkrets 26 cm, areal 36 cm². B: omkrets 20 cm, areal 25 cm². C: omkrets 30 cm, areal 36 cm²","ekstra":[]},{"id":"M5B-5.50","bok":"5.50 a-c","side":"32","kap":5,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 5)","type":"Visuell oppgave","niva":3,"figur":true,"ferdighet":"Finne arealet av sammensatte figurer ved å dele i rektangler/trekanter","q":"Finn arealet. a) To rektangler 8 · 2 og 3 · 4 satt sammen. b) Tre rektangler 5 · 2, 3 · 2 og 1 · 2 satt i trapp. c) Et rektangel 10 · 6 med et hull på 4 · 3.","a":"a) 16 + 12 = 28. b) 10 + 6 + 2 = 18. c) 60 − 12 = 48 (alle i cm²)","ekstra":[]},{"id":"M5B-5.51","bok":"5.51","side":"33","kap":5,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 5)","type":"Tolk data","niva":3,"figur":true,"ferdighet":"Finne arealet av plen A ut fra oppgitt omkrets, side og areal av andre deler","q":"En hage er 20 m · 30 m. Plen B er 10 m · 12 m, og et blomsterbed er 6 m · 5 m. Resten er plen A. Hvor stort areal har A?","a":"Hage 20 · 30 = 600 m². B = 120 m². Bed = 30 m². A = 600 − 120 − 30 = 450 m²","ekstra":[]},{"id":"M5B-5.52","bok":"5.52","side":"33","kap":5,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 5)","type":"Tolk data","niva":3,"figur":true,"ferdighet":"Finne arealet av plen B ut fra omkrets og én side","q":"En plen er et rektangel med omkrets 36 m og bredde 7 m. Hvor stort areal har den?","a":"Lengde + bredde = 18 m. Lengde 18 − 7 = 11 m. Areal 11 · 7 = 77 m²","ekstra":[]},{"id":"M5B-6.1","bok":"6.1 a-b","side":"35","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Visuell oppgave","niva":1,"figur":true,"ferdighet":"Skrive brøk for en farge i et lite antall brikker (grønne, røde)","q":"En rad har 6 brikker: 2 røde, 3 blå og 1 grønn. a) Hvor stor del er blå? b) Hvor stor del er grønn?","a":"a) 3/6. b) 1/6","ekstra":[]},{"id":"M5B-6.2","bok":"6.2 a-b","side":"35","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Visuell oppgave","niva":1,"figur":true,"ferdighet":"Skrive brøk for en farge når brikkene ligger spredt (gule, blå)","q":"8 brikker: 3 gule, 4 blå og 1 rød. a) Hvor stor del er blå? b) Hvor stor del er røde?","a":"a) 4/8. b) 1/8","ekstra":[]},{"id":"M5B-6.3","bok":"6.3 a-b","side":"35","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Finne brøk for én farge og for to farger sammen (grønne og blå)","q":"10 brikker: 3 røde, 4 grønne, 2 blå og 1 gul. a) Hvor stor del er røde? b) Hvor stor del er grønne og blå sammen?","a":"a) 3/10. b) 4/10 + 2/10 = 6/10","ekstra":[]},{"id":"M5B-6.4","bok":"6.4 a-f","side":"36","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Finne hvor stor del av barna som har caps på hodet; oppdage hvilken gruppe som har mer enn halvparten","q":"Hvor stor del av barna har caps? a) 5 av 12 barn. b) 3 av 8 barn. c) 5 av 9 barn. I hvilken av oppgavene har mer enn halvparten caps?","a":"a) 5/12. b) 3/8. c) 5/9. Bare c har mer enn halvparten (5 av 9 er mer enn 4,5)","ekstra":[]},{"id":"M5B-6.5","bok":"6.5 a-e","side":"36","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Tolk data","niva":2,"figur":true,"ferdighet":"Telle kuler i tre farger og lage tabell med brøk for hver farge","q":"a) 10 kuler: 4 røde, 3 gule og 3 svarte. b) 12 kuler: 5 røde, 4 gule og 3 svarte. Lag tabell med brøk for hver farge.","a":"a) Røde 4/10, gule 3/10, svarte 3/10. b) Røde 5/12, gule 4/12, svarte 3/12","ekstra":[]},{"id":"M5B-6.6","bok":"6.6 a-b","side":"37","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Tolk data","niva":2,"figur":true,"ferdighet":"Finne hvor stor del av kakene som er igjen og spist, og skrive i tabell","q":"Kake A er delt i 8 like biter og 3 er spist. Kake B er delt i 12 biter og 9 er spist. Lag tabell: igjen og spist.","a":"A: igjen 5/8, spist 3/8. B: igjen 3/12, spist 9/12","ekstra":[]},{"id":"M5B-6.7","bok":"6.7 a-b","side":"37","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Forklar og begrunn","niva":3,"figur":true,"ferdighet":"Finne brøken som gir gevinst på lykkehjul og velge hjulet som lønner seg mest","q":"Du vinner på rødt felt. Hjul 1 har 8 like felt, 3 røde. Hjul 2 har 6 like felt, 2 røde. Hjul 3 har 10 like felt, 4 røde. a) Hvor stor del gir gevinst? b) Hvilket hjul lønner seg best?","a":"a) 3/8, 2/6 og 4/10. b) Hjul 3: 4/10 = 0,4 er mer enn 3/8 = 0,375 og 2/6 ≈ 0,33","ekstra":[]},{"id":"M5B-6.8","bok":"6.8 a-b","side":"38","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Visuell oppgave","niva":1,"figur":true,"ferdighet":"Lese av hvor stor del av en figur som er rød og blå (seks figurer A-F)","q":"En sirkel er delt i 10 like deler. 3 deler er røde og resten blå. a) Hvor stor del er rød? b) Hvor stor del er blå?","a":"a) 3/10. b) 7/10","ekstra":[]},{"id":"M5B-6.9","bok":"6.9","side":"38","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Finne figurer der 2/3 er fargelagt, også når delene er flere enn tre","q":"Fire rektangler er delt i 6 like deler. Antall fargelagte deler: A 4, B 3, C 2, D 4. Hvilke rektangler har 2/3 fargelagt?","a":"A og D (4/6 = 2/3)","ekstra":[]},{"id":"M5B-6.10","bok":"6.10","side":"38","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Finne figurer der 3/4 er fargelagt, også når delene er flere enn fire","q":"Fire figurer er delt i 8 like deler. Antall fargelagte deler: A 6, B 3, C 6, D 4. Hvilke figurer har 3/4 fargelagt?","a":"A og C (6/8 = 3/4)","ekstra":[]},{"id":"M5B-6.11","bok":"6.11","side":"39","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Visuell oppgave","niva":1,"figur":false,"ferdighet":"Tegne og fargelegge en gitt brøkdel av forskjellige figurer","q":"Tegn en sirkel og et rektangel. Del hver figur i 6 like deler og fargelegg 1/3 av hver.","a":"2 av 6 deler fargelagt i hver figur (2/6 = 1/3)","ekstra":[]},{"id":"M5B-6.12","bok":"6.12 a-b","side":"39","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Åpen utforsking","niva":2,"figur":false,"ferdighet":"Vise at en brøkdel kan fargelegges på forskjellige måter","q":"a) Tegn tre like rektangler. b) Fargelegg 1/2 av hvert rektangel på tre ulike måter.","a":"Åpen. Eksempel: loddrett halvdel, vannrett halvdel og diagonal halvdel. Alle har to like store deler.","ekstra":[]},{"id":"M5B-6.13","bok":"6.13 a-b","side":"39","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Spill / aktivitet","niva":2,"figur":false,"ferdighet":"Brette og klippe papir i like deler og fargelegge brøker","q":"Bruk et ark. a) Brett det i 8 like deler. Fargelegg 2/8 grønt og 6/8 blått. b) Brett et nytt ark i 6 like deler. Fargelegg 1/6 rødt, 2/6 gult og 3/6 blått.","a":"a) 2 grønne og 6 blå deler. b) 1 rød, 2 gule og 3 blå deler. Summen er 1 hel i begge.","ekstra":[]},{"id":"M5B-6.14","bok":"6.14 a-b","side":"39","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Åpen utforsking","niva":2,"figur":true,"ferdighet":"Dele en figur i like store deler på ulike måter","q":"Tegn et rektangel. a) Del det i to like store deler. Kan du gjøre det på flere måter? b) Del et rektangel i fire like store deler.","a":"a) Ja: f.eks. loddrett, vannrett eller langs en diagonal. b) Ja: f.eks. fire striper eller to midtlinjer som krysser hverandre.","ekstra":[]},{"id":"M5B-6.15","bok":"6.15 a-d","side":"40","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Tegne hele figuren når 1/2 er gitt (trekant, rektangel, halvsirkel)","q":"Et rektangel på 2 · 3 ruter er 1/2 av en figur. Tegn hele figuren. Hvor mange ruter har den?","a":"6 ruter · 2 = 12 ruter, f.eks. et rektangel på 4 · 3 ruter","ekstra":[]},{"id":"M5B-6.16","bok":"6.16 a-d","side":"40","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Tegne hele figuren på prikkrutenett når 1/2, 1/3, 1/5 eller 1/6 er gitt","q":"En figur på 2 ruter er 1/5 av hele figuren. Hvor mange ruter er hele figuren?","a":"2 · 5 = 10 ruter","ekstra":[]},{"id":"M5B-6.17","bok":"6.17 a-c","side":"40","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Visuell oppgave","niva":3,"figur":true,"ferdighet":"Tegne hele figuren når flere deler er gitt (2/6 og en L-form)","q":"En figur på 4 ruter er 2/5 av hele figuren. Hvor mange ruter er hele figuren?","a":"4 : 2 = 2 ruter per femdel. 2 · 5 = 10 ruter","ekstra":[]},{"id":"M5B-6.18","bok":"6.18","side":"40","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Visuell oppgave","niva":3,"figur":true,"ferdighet":"Tegne hele figuren når 2/3 er gitt","q":"Et rektangel på 6 ruter er 2/3 av en figur. Hvor mange ruter er hele figuren?","a":"6 : 2 = 3 ruter per tredel. 3 · 3 = 9 ruter","ekstra":[]},{"id":"M5B-6.19","bok":"6.19 a-d","side":"41","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Tegne hele figuren på rutenett når en liten del (1/4, 1/3, 1/6, 1/2) er gitt","q":"En rute er a) 1/4 b) 1/8 av en figur. Hvor mange ruter er hele figuren?","a":"a) 4 ruter. b) 8 ruter","ekstra":[]},{"id":"M5B-6.20","bok":"6.20 a-c","side":"41","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Tegne hele figuren når delen er rektangel, trekant eller rute","q":"En del på 3 ruter er a) 1/2 b) 1/3 c) 1/4 av en figur. Hvor mange ruter har hele figuren?","a":"a) 6. b) 9. c) 12","ekstra":[]},{"id":"M5B-6.21","bok":"6.21 a-f","side":"41","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","type":"Visuell oppgave","niva":3,"figur":true,"ferdighet":"Tegne alle kulene når en brøkdel av kulene er gitt","q":"a) 4 røde kuler er 1/2 av alle kulene. Hvor mange kuler er det? b) 3 blå kuler er 1/3 av alle. c) 6 grønne kuler er 2/3 av alle.","a":"a) 8 kuler. b) 9 kuler. c) 6 : 2 = 3 per tredel, 3 · 3 = 9 kuler","ekstra":[]},{"id":"M5B-6.22","bok":"6.22 a-c","side":"42","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Skrive brøk når teller og nevner er oppgitt","q":"Skriv en brøk der a) telleren er 3 og nevneren er 7 b) telleren er 5 og nevneren er 8 c) nevneren er 12 og telleren er 11","a":"a) 3/7. b) 5/8. c) 11/12","ekstra":[]},{"id":"M5B-6.23","bok":"6.23 a-b","side":"42","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Doble og halvere teller og nevner for å lage en ny brøk","q":"a) Skriv en ny brøk der teller og nevner er dobbelt så store som i 3/5. b) Skriv en ny brøk der teller og nevner er halvparten så store som i 6/10.","a":"a) 6/10. b) 3/5","ekstra":[]},{"id":"M5B-6.24","bok":"6.24","side":"42","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Mønster og logikk","niva":2,"figur":false,"ferdighet":"Lage brøker med en gitt sammenheng mellom teller og nevner","q":"Skriv tre brøker der nevneren er tre ganger så stor som telleren.","a":"F.eks. 1/3, 2/6, 3/9, 4/12","ekstra":[]},{"id":"M5B-6.25","bok":"6.25","side":"42","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Mønster og logikk","niva":2,"figur":false,"ferdighet":"Lage brøker der telleren er mindre enn nevneren med en fast differanse","q":"Skriv tre brøker der telleren er 3 mindre enn nevneren.","a":"F.eks. 1/4, 2/5, 5/8, 7/10","ekstra":[]},{"id":"M5B-6.26","bok":"6.26","side":"42","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Mønster og logikk","niva":2,"figur":false,"ferdighet":"Skrive brøker som har samme verdi som en gitt brøk","q":"Skriv tre brøker som har samme verdi som 1/3.","a":"F.eks. 2/6, 3/9, 4/12, 5/15","ekstra":[]},{"id":"M5B-6.27","bok":"6.27 a-c","side":"43","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Dele figur i mindre like deler og finne ny brøk med samme verdi (1/2 = ?/4)","q":"a) Tegn en sirkel og fargelegg halvparten. b) Del den i åttedeler. c) Hvor mange åttedeler er fargelagt? 1/2 = ?/8","a":"c) 4 åttedeler. 1/2 = 4/8","ekstra":[]},{"id":"M5B-6.28","bok":"6.28 a-c","side":"43","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Dele inn i flere like deler og finne brøk med samme verdi (1/3 = ?/6)","q":"a) Tegn et rektangel og fargelegg 1/4. b) Del det inn i åttedeler. c) Hvor mange åttedeler er fargelagt? 1/4 = ?/8","a":"c) 2 åttedeler. 1/4 = 2/8","ekstra":[]},{"id":"M5B-6.29","bok":"6.29 a-c","side":"43","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Utvide brøk med figur (2/5 = ?/10)","q":"a) Tegn en figur og fargelegg 3/4. b) Del den i åttedeler. c) Hvor mange åttedeler er fargelagt? 3/4 = ?/8","a":"c) 6 åttedeler. 3/4 = 6/8","ekstra":[]},{"id":"M5B-6.30","bok":"6.30 a-c","side":"43","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Utvide brøk med figur (3/4 = ?/12)","q":"a) Tegn en figur og fargelegg 2/3. b) Del den i niendedeler. c) Hvor mange niendedeler er fargelagt? 2/3 = ?/9","a":"c) 6 niendedeler. 2/3 = 6/9","ekstra":[]},{"id":"M5B-6.31","bok":"6.31 a-c","side":"43","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Visuell oppgave","niva":3,"figur":true,"ferdighet":"Utvide brøk med figur (4/10 = ?/20)","q":"a) Tegn en figur og fargelegg 6/10. b) Del den i tjuendedeler. c) Hvor mange tjuendedeler er fargelagt? 6/10 = ?/20","a":"c) 12 tjuendedeler. 6/10 = 12/20","ekstra":[]},{"id":"M5B-6.32","bok":"6.32 a-c","side":"44","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Doble teller og nevner (ni brøker)","q":"Skriv brøker der teller og nevner er dobbelt så store. a) 1/6 b) 3/5 c) 2/9 d) 5/7 e) 3/8 f) 4/9","a":"a) 2/12. b) 6/10. c) 4/18. d) 10/14. e) 6/16. f) 8/18","ekstra":[]},{"id":"M5B-6.33","bok":"6.33 a-c","side":"44","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Halvere teller og nevner (ni brøker)","q":"Skriv brøker der teller og nevner er halvparten så store. a) 6/10 b) 10/12 c) 4/8 d) 12/18 e) 14/16 f) 8/20","a":"a) 3/5. b) 5/6. c) 2/4. d) 6/9. e) 7/8. f) 4/10","ekstra":[]},{"id":"M5B-6.34","bok":"6.34 a-d","side":"45","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Finne brøker som er like store, lik 1, nesten 1 og som blir 1 sammen, fra en samling brøker","q":"Brøkene: 1/4, 2/8, 3/5, 6/6, 4/5, 2/3, 5/5, 3/4. Hvilke a) er like store b) er lik en hel c) har teller som er én mindre enn nevneren d) blir én hel hvis du legger dem sammen?","a":"a) 1/4 og 2/8. b) 6/6 og 5/5. c) 4/5, 2/3 og 3/4. d) 1/4 og 3/4","ekstra":[]},{"id":"M5B-6.35","bok":"6.35","side":"45","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Finne brøker som har samme verdi som 1/4 ut fra en figur","q":"Hvilke av 2/6, 3/9, 4/10, 5/15 og 6/12 har samme verdi som 1/3?","a":"2/6, 3/9 og 5/15 (4/10 = 2/5 og 6/12 = 1/2)","ekstra":[]},{"id":"M5B-6.36","bok":"6.36","side":"45","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Koble brøker i to grupper (A og B) som har samme verdi","q":"A: 1/2, 3/4, 2/5. B: 4/10, 6/8, 5/10. Skriv brøkene i A og B som har samme verdi.","a":"1/2 = 5/10. 3/4 = 6/8. 2/5 = 4/10","ekstra":[]},{"id":"M5B-6.37","bok":"6.37 a-c","side":"46","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Lage regnestykker som blir 1 ut fra figurer med fargede deler","q":"a) En stripe er delt i 7 like deler, og 3 er farget. b) En stripe er delt i 10 deler, og 4 er farget. Lag regnestykker som blir 1.","a":"a) 3/7 + 4/7 = 7/7 = 1. b) 4/10 + 6/10 = 10/10 = 1","ekstra":[]},{"id":"M5B-6.38","bok":"6.38 a-b","side":"46","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Finne manglende brøk når summen er 1","q":"Hvilken brøk mangler? a) 1/3 + ? = 1 b) 5/8 + ? = 1 c) ? + 2/9 = 1 d) ? + 3/10 = 1","a":"a) 2/3. b) 3/8. c) 7/9. d) 7/10","ekstra":[]},{"id":"M5B-6.39","bok":"6.39","side":"46","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Mønster og logikk","niva":2,"figur":true,"ferdighet":"Velge én brøk fra A og én fra B slik at summen blir 1","q":"A: 1/4, 2/5, 3/7. B: 3/5, 4/7, 3/4. Velg én fra A og én fra B slik at summen blir 1.","a":"1/4 + 3/4. 2/5 + 3/5. 3/7 + 4/7","ekstra":[]},{"id":"M5B-6.40","bok":"6.40 a-d","side":"46","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Finne manglende teller i regnestykker med 2-3 ledd som blir 1","q":"Hvilket tall mangler? a) ?/9 + 4/9 = 1 b) 2/8 + ?/8 + 3/8 = 1 c) 7/15 + ?/15 = 1","a":"a) 5. b) 3. c) 8","ekstra":[]},{"id":"M5B-6.41","bok":"6.41 a-d","side":"47","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Tideler og tallinje","type":"Tolk data","niva":2,"figur":true,"ferdighet":"Lese av litermål med tideler, legge sammen og sammenligne, skrive som brøk og desimaltall","q":"Tre litermål (1 liter delt i 10) har saft: P 2/10, Q 5/10, R 9/10. a) Skriv hvor mye saft det er i hvert mål som brøk. b) Hvor mye er det til sammen i P og Q? c) Hvor mye mer er det i R enn i Q? d) Skriv alle tre som desimaltall.","a":"a) 2/10, 5/10, 9/10. b) 7/10. c) 4/10. d) 0,2; 0,5; 0,9","ekstra":[["Tall og regning","Tall og tallinje"]]},{"id":"M5B-6.42","bok":"6.42 a-b","side":"47","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Tideler og tallinje","type":"Tekstoppgave","niva":2,"figur":true,"ferdighet":"Lese av saft i mugger og finne hvor mye som mangler til 1 liter","q":"Tre mugger rommer 1 liter hver. X har 4/10 liter saft, Y har 7/10 og Z har 1/10. a) Hvor mye saft er det i hver mugge? b) Hvor mye mer må fylles på for at hver mugge skal bli full?","a":"a) 4/10, 7/10, 1/10. b) 6/10, 3/10, 9/10","ekstra":[["Tall og regning","Tall og tallinje"]]},{"id":"M5B-6.43","bok":"6.43 a-b","side":"48","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Tideler og tallinje","type":"Ferdighetstrening","niva":1,"figur":true,"ferdighet":"Lese av brøk og desimaltall på tallinje 0-1 delt i tideler","q":"På en tallinje fra 0 til 1 delt i 10 deler peker pil A på 3. strek og pil B på 8. strek. Skriv både som brøk og som desimaltall.","a":"A = 3/10 = 0,3. B = 8/10 = 0,8","ekstra":[["Tall og regning","Tall og tallinje"]]},{"id":"M5B-6.44","bok":"6.44 a-b","side":"48","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Tideler og tallinje","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Ordne tideler i rekkefølge og skrive som desimaltall","q":"a) Skriv brøkene i rekkefølge, minst først: 6/10, 2/10, 9/10, 4/10. b) Skriv dem som desimaltall.","a":"a) 2/10, 4/10, 6/10, 9/10. b) 0,2; 0,4; 0,6; 0,9","ekstra":[["Tall og regning","Tall og tallinje"]]},{"id":"M5B-6.45","bok":"6.45 a-c","side":"48","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Tideler og tallinje","type":"Tolk data","niva":2,"figur":true,"ferdighet":"Lese av brøk og telle tideler mellom to punkter på en tallinje","q":"Pil A står på 2/10 og pil B på 7/10 på en tallinje fra 0 til 1. a) Hvilken brøk peker B på? b) Hvor mange tideler er det mellom A og B? c) Hvor mange tideler er det fra A til 1?","a":"a) 7/10. b) 5 tideler. c) 8 tideler","ekstra":[["Tall og regning","Tall og tallinje"]]},{"id":"M5B-6.46","bok":"6.46 a-c","side":"48","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Tideler og tallinje","type":"Ferdighetstrening","niva":3,"figur":true,"ferdighet":"Tegne tallinje med tideler og merke av brøker, også tall over 1 og dobbelt så stor","q":"Tegn en tallinje fra 0 til 2 delt i tideler. a) Merk av D = 3/10. b) Merk av E som er dobbelt så stor som D. c) Merk av 1 4/10.","a":"a) D = 0,3. b) E = 6/10 = 0,6. c) 1 4/10 = 1,4 (4 streker etter 1)","ekstra":[["Tall og regning","Tall og tallinje"]]},{"id":"M5B-6.47","bok":"6.47","side":"49","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Tideler og tallinje","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Lese av seks piler på tallinje og skrive både brøk og desimaltall","q":"En tallinje fra 0 til 1 er delt i tideler. Fire piler peker på 1., 4., 6. og 9. strek. Skriv både brøk og desimaltall for hver pil.","a":"1/10 = 0,1; 4/10 = 0,4; 6/10 = 0,6; 9/10 = 0,9","ekstra":[["Tall og regning","Tall og tallinje"]]},{"id":"M5B-6.48","bok":"6.48 a-b","side":"49","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Tideler og tallinje","type":"Ferdighetstrening","niva":3,"figur":true,"ferdighet":"Finne avstander mellom tall på tallinja og finne to tall med gitt avstand","q":"a) Hvor langt er det fra 0,2 til 0,7? Fra 3/10 til 9/10? Fra 0,6 til 1? b) Finn to tall på tallinja som har avstanden 0,4.","a":"a) 0,5. 6/10. 0,4. b) F.eks. 0,1 og 0,5; 0,3 og 0,7; 0,6 og 1","ekstra":[["Tall og regning","Tall og tallinje"]]},{"id":"M5B-6.49","bok":"6.49","side":"49","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Tideler og tallinje","type":"Mønster og logikk","niva":2,"figur":true,"ferdighet":"Velge ett desimaltall og én brøk slik at summen blir 1","q":"A: 0,4; 0,7; 0,1. B: 3/10, 6/10, 9/10. Velg ett desimaltall fra A og én brøk fra B slik at summen blir 1.","a":"0,4 + 6/10 = 1. 0,7 + 3/10 = 1. 0,1 + 9/10 = 1","ekstra":[["Tall og regning","Tall og tallinje"]]},{"id":"M5B-6.50","bok":"6.50 a-d","side":"50","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Tideler og tallinje","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Sette <, > eller = mellom brøker og regnestykker med brøk","q":"Skriv riktig tegn (<, > eller =): a) 1/3 og 2/6 b) 3/4 og 1/2 c) 2/5 og 3/5 d) 3/7 + 4/7 og 1 e) 7/9 - 4/9 og 1/3","a":"a) =. b) >. c) <. d) =. e) = (3/9 = 1/3)","ekstra":[["Tall og regning","Tall og tallinje"]]},{"id":"M5B-6.51","bok":"6.51 a-e","side":"50","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Tideler og tallinje","type":"Mønster og logikk","niva":3,"figur":false,"ferdighet":"Finne de tre neste brøkene i en tallfølge","q":"Hvilke tre brøker kommer videre? a) 1/9, 2/9, 3/9 ... b) 12/15, 10/15, 8/15 ... c) 1/3, 2/4, 3/5 ... d) 1/2, 2/4, 3/6 ...","a":"a) 4/9, 5/9, 6/9. b) 6/15, 4/15, 2/15. c) 4/6, 5/7, 6/8. d) 4/8, 5/10, 6/12","ekstra":[["Tall og regning","Tall og tallinje"]]},{"id":"M5B-SPILL-S50","bok":"Spill: Brøk","side":"50","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Tideler og tallinje","type":"Spill / aktivitet","niva":2,"figur":true,"ferdighet":"Spill med brøkbrikker som dekker et brett; summere brøker til én hel","q":"Spill sammen to og to. Hver spiller har en stripe delt i 12 like ruter. Kast terning: tallet n gir at du får fargelegge n/12. Første som fyller nøyaktig 12/12 vinner.","a":"Ingen fasit; spill. Sjekk at 12/12 = 1.","ekstra":[["Tall og regning","Tall og tallinje"]]},{"id":"M5B-6.52","bok":"6.52 a-d","side":"51","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","type":"Ferdighetstrening","niva":1,"figur":true,"ferdighet":"Legge sammen brøker med lik nevner ut fra figurer","q":"En sirkel er delt i 8 like deler. 3 deler er gule og 2 er røde. Regn ut 3/8 + 2/8. En stripe er delt i 6 deler, 1 blå og 4 grønne. Regn ut 1/6 + 4/6.","a":"5/8. 5/6","ekstra":[]},{"id":"M5B-6.53","bok":"6.53 a-c","side":"51","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Legge sammen to brøker med lik nevner","q":"Regn ut. a) 3/9 + 4/9 b) 1/6 + 2/6 c) 2/10 + 5/10 d) 4/11 + 3/11","a":"a) 7/9. b) 3/6. c) 7/10. d) 7/11","ekstra":[]},{"id":"M5B-6.54","bok":"6.54 a-d","side":"51","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Legge sammen tre brøker med lik nevner","q":"Regn ut. a) 1/12 + 4/12 + 5/12 b) 2/9 + 3/9 + 1/9 c) 3/15 + 4/15 + 6/15","a":"a) 10/12. b) 6/9. c) 13/15","ekstra":[]},{"id":"M5B-6.55","bok":"6.55 a-b","side":"51","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","type":"Åpen utforsking","niva":2,"figur":true,"ferdighet":"Lage egne regnestykker med brøker ut fra bilde av grupper av figurer","q":"Du har 8 figurer: 3 blå, 2 røde og 3 gule. Lag regnestykker med brøker.","a":"Åpen. F.eks. 3/8 + 2/8 = 5/8 og 3/8 + 2/8 + 3/8 = 8/8 = 1","ekstra":[]},{"id":"M5B-6.56","bok":"6.56 a-f","side":"52","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Bruke tallinje til å skrive regnestykke og finne svaret","q":"Bruk en tallinje delt i niendedeler, sjetteledeler og tideler og regn ut: a) 3/9 + 4/9 b) 2/6 + 3/6 c) 4/10 + 5/10","a":"a) 7/9. b) 5/6. c) 9/10","ekstra":[]},{"id":"M5B-6.57","bok":"6.57 a-d","side":"52","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Legge sammen to brøker med lik nevner","q":"Regn ut. a) 2/9 + 5/9 b) 3/8 + 2/8 c) 4/10 + 5/10 d) 1/7 + 3/7","a":"a) 7/9. b) 5/8. c) 9/10. d) 4/7","ekstra":[]},{"id":"M5B-6.58","bok":"6.58 a-d","side":"52","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Legge sammen tre brøker med lik nevner","q":"Regn ut. a) 1/10 + 3/10 + 4/10 b) 3/12 + 2/12 + 5/12 c) 2/15 + 6/15 + 4/15","a":"a) 8/10. b) 10/12. c) 12/15","ekstra":[]},{"id":"M5B-6.59","bok":"6.59 a-d","side":"53","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","type":"Ferdighetstrening","niva":1,"figur":true,"ferdighet":"Trekke fra brøker med lik nevner ut fra figur","q":"Regn ut. a) 5/7 - 2/7 b) 7/9 - 3/9 (figurene viser sirkler delt i like deler)","a":"a) 3/7. b) 4/9","ekstra":[]},{"id":"M5B-6.60","bok":"6.60 a-d","side":"53","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Trekke fra brøker, også med svar 0","q":"Regn ut. a) 6/8 - 1/8 b) 9/9 - 4/9 c) 8/12 - 5/12 d) 5/5 - 5/5","a":"a) 5/8. b) 5/9. c) 3/12. d) 0","ekstra":[]},{"id":"M5B-6.61","bok":"6.61 a-f","side":"53","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Trekke fra brøker med lik nevner","q":"Regn ut. a) 9/10 - 4/10 b) 11/12 - 6/12 c) 14/15 - 9/15 d) 6/7 - 2/7","a":"a) 5/10. b) 5/12. c) 5/15. d) 4/7","ekstra":[]},{"id":"M5B-6.62","bok":"6.62 a-d","side":"54","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Finne forskjellen mellom to fargelagte områder med figur og regne ut","q":"En stripe delt i 10 deler har 8 deler farget. En annen like stor stripe har 5 deler farget. Skriv regnestykket og finn forskjellen.","a":"8/10 - 5/10 = 3/10","ekstra":[]},{"id":"M5B-6.63","bok":"6.63 a-b","side":"54","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","type":"Tekstoppgave","niva":3,"figur":false,"ferdighet":"Tolke tekst om to personer og finne både forskjell og rest som summeres","q":"Mia og Jonas kjøper hver sin sjokolade av samme type. Mia spiser 5/6 av sin og Jonas spiser 2/6 av sin. a) Hvor mye mer spiser Mia enn Jonas? Lise får det som er igjen fra begge. b) Hvor mye sjokolade får Lise?","a":"a) 5/6 - 2/6 = 3/6. b) Mia har 1/6 igjen, Jonas 4/6 igjen. 1/6 + 4/6 = 5/6","ekstra":[]},{"id":"M5B-6.64","bok":"6.64 a-b","side":"55","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","type":"Ferdighetstrening","niva":1,"figur":true,"ferdighet":"Bruke tallinje til å regne subtraksjon av brøker","q":"Bruk tallinjen og regn ut. a) 6/8 - 2/8 b) 8/10 - 3/10","a":"a) 4/8. b) 5/10","ekstra":[]},{"id":"M5B-6.65","bok":"6.65 a-f","side":"55","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Trekke fra brøker med lik nevner, ulike nevnere som 12, 13, 18","q":"Regn ut. a) 8/9 - 3/9 b) 11/12 - 4/12 c) 12/14 - 7/14 d) 9/16 - 2/16","a":"a) 5/9. b) 7/12. c) 5/14. d) 7/16","ekstra":[]},{"id":"M5B-6.66","bok":"6.66","side":"55","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Kombinere addisjon og subtraksjon av brøker på tallinje","q":"Regn ut med tallinje. a) 5/10 + 3/10 - 4/10 b) 2/10 + 6/10 - 5/10","a":"a) 8/10 - 4/10 = 4/10. b) 8/10 - 5/10 = 3/10","ekstra":[]},{"id":"M5B-6.67","bok":"6.67 a-b","side":"56","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Blandede tall","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Legge sammen brøker med figur og skrive svaret som blandet tall","q":"Regn ut. a) 4/5 + 3/5 b) 5/8 + 5/8 (figurene viser to striper delt i like deler)","a":"a) 7/5 = 1 2/5. b) 10/8 = 1 2/8","ekstra":[]},{"id":"M5B-6.68","bok":"6.68 a-b","side":"56","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Blandede tall","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Legge sammen brøker med sirkelfigur og få mer enn 1","q":"Hvor mye er det til sammen? a) 3/4 + 3/4 b) 7/10 + 5/10","a":"a) 6/4 = 1 2/4. b) 12/10 = 1 2/10","ekstra":[]},{"id":"M5B-6.69","bok":"6.69 a-f","side":"56","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Blandede tall","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Legge sammen brøker og skrive svar som blandet tall","q":"Regn ut. a) 4/6 + 5/6 b) 8/10 + 7/10 c) 6/7 + 4/7 d) 9/12 + 8/12","a":"a) 9/6 = 1 3/6. b) 15/10 = 1 5/10. c) 10/7 = 1 3/7. d) 17/12 = 1 5/12","ekstra":[]},{"id":"M5B-6.70","bok":"6.70 a-d","side":"57","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Blandede tall","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Bruke tallinje til å legge sammen brøker som blir mer enn 1","q":"Bruk tallinje og regn ut. a) 3/5 + 4/5 b) 2/6 + 3/6 + 4/6","a":"a) 7/5 = 1 2/5. b) 9/6 = 1 3/6","ekstra":[]},{"id":"M5B-6.71","bok":"6.71 a-f","side":"57","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Blandede tall","type":"Ferdighetstrening","niva":3,"figur":false,"ferdighet":"Legge sammen flere brøker og blandede tall med lik nevner","q":"Regn ut. a) 3/6 + 2/6 + 1/6 b) 3/5 + 3/5 + 2/5 c) 1 1/4 + 2/4 d) 1 3/7 + 2/7","a":"a) 6/6 = 1. b) 8/5 = 1 3/5. c) 1 3/4. d) 1 5/7","ekstra":[]},{"id":"M5B-6.72","bok":"6.72 a-d","side":"58","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Blandede tall","type":"Ferdighetstrening","niva":3,"figur":true,"ferdighet":"Bruke tallinje til å trekke fra brøker fra blandede tall","q":"Bruk tallinjen og regn ut. a) 1 3/5 - 2/5 b) 1 1/5 - 3/5 c) 1 2/6 - 4/6 d) 1 4/8 - 1","a":"a) 1 1/5. b) 3/5. c) 4/6. d) 4/8","ekstra":[]},{"id":"M5B-6.73","bok":"6.73 a-d","side":"58","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Blandede tall","type":"Ferdighetstrening","niva":3,"figur":false,"ferdighet":"Trekke fra fra blandede tall og fra hele tall","q":"Regn ut. a) 1 4/7 - 2/7 b) 1 2/7 - 5/7 c) 2 - 1/3 d) 2 - 5/6","a":"a) 1 2/7. b) 4/7. c) 1 2/3. d) 1 1/6","ekstra":[]},{"id":"M5B-6.74","bok":"6.74 a-b","side":"58","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Blandede tall","type":"Ferdighetstrening","niva":3,"figur":false,"ferdighet":"Regne med flere ledd og blandede tall","q":"Regn ut. a) 2/7 + 4/7 - 3/7 + 5/7 b) 5/6 - 2/6 + 1 1/6","a":"a) 8/7 = 1 1/7. b) 3/6 + 1 1/6 = 1 4/6","ekstra":[]},{"id":"M5B-PROVE-1","bok":"Prøve 1","side":"60","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":1,"figur":true,"ferdighet":"Finne hvor stor del av en mengde kuler som har en farge","q":"Det er 10 kuler: 4 grønne, 5 røde og 1 blå. Hvor stor del av kulene er grønne, røde og blå?","a":"Grønne 4/10. Røde 5/10. Blå 1/10","ekstra":[]},{"id":"M5B-PROVE-2","bok":"Prøve 2 a-c","side":"60","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":1,"figur":true,"ferdighet":"Lese av fargelagt del i figurer","q":"Hvor stor del er fargelagt? a) 2 · 2 ruter der 3 er farget b) sirkel delt i 8 der 5 er farget","a":"a) 3/4. b) 5/8","ekstra":[]},{"id":"M5B-PROVE-3","bok":"Prøve 3 a-c","side":"60","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Tegne hele figuren når 1/2, 1/3 eller 1/4 er gitt","q":"Delen er a) 2 ruter og er 1/2 b) 2 ruter og er 1/3 c) 2 ruter og er 1/4. Hvor mange ruter er hele figuren?","a":"a) 4. b) 6. c) 8","ekstra":[]},{"id":"M5B-PROVE-4","bok":"Prøve 4 a-c","side":"60","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Finne manglende tall i likeverdige brøker","q":"a) 1/3 = ?/9 b) 2/4 = ?/8 c) 3/5 = 9/?","a":"a) 3. b) 4. c) 15","ekstra":[]},{"id":"M5B-PROVE-5","bok":"Prøve 5","side":"60","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Velge brøker som har samme verdi som 1/3","q":"Hvilke av 2/4, 3/6, 4/10, 5/10 og 3/4 har samme verdi som 1/2?","a":"2/4, 3/6 og 5/10","ekstra":[]},{"id":"M5B-PROVE-6","bok":"Prøve 6","side":"61","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":1,"figur":true,"ferdighet":"Lese av brøk på tallinje med piler A og B","q":"En tallinje fra 0 til 1 er delt i tideler. Pil A står på 2. strek og pil B på 7. strek. Hvilke brøker peker pilene på?","a":"A = 2/10. B = 7/10","ekstra":[]},{"id":"M5B-PROVE-7","bok":"Prøve 7 a-d","side":"61","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Skrive tideler som desimaltall","q":"Skriv som desimaltall. a) 6/10 b) 9/10 c) 2/10 d) 4/10","a":"a) 0,6. b) 0,9. c) 0,2. d) 0,4","ekstra":[]},{"id":"M5B-PROVE-8","bok":"Prøve 8 a-d","side":"61","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Skrive desimaltall som brøk","q":"Skriv som brøk. a) 0,3 b) 0,7 c) 0,5 d) 0,1","a":"a) 3/10. b) 7/10. c) 5/10. d) 1/10","ekstra":[]},{"id":"M5B-PROVE-9","bok":"Prøve 9 a-c","side":"61","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Regne med brøker med lik nevner","q":"Regn ut. a) 3/7 + 2/7 b) 5/9 + 3/9 c) 9/10 - 4/10","a":"a) 5/7. b) 8/9. c) 5/10","ekstra":[]},{"id":"M5B-PROVE-10","bok":"Prøve 10 a-c","side":"61","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Finne manglende brøk","q":"Hvilken brøk mangler? a) 2/5 + ? = 1 b) ? + 4/7 = 1 c) 1/8 + ? = 6/8","a":"a) 3/5. b) 3/7. c) 5/8","ekstra":[]},{"id":"M5B-PROVE-11","bok":"Prøve 11 a-b","side":"61","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Regne med tre ledd","q":"Regn ut. a) 3/12 + 4/12 + 2/12 b) 7/8 - 3/8 + 2/8","a":"a) 9/12. b) 6/8","ekstra":[]},{"id":"M5B-PROVE-12","bok":"Prøve 12 a-b","side":"61","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":3,"figur":false,"ferdighet":"Legge sammen og trekke fra med blandede tall","q":"Regn ut. a) 5/6 + 4/6 b) 1 2/5 - 3/5","a":"a) 9/6 = 1 3/6. b) 7/5 - 3/5 = 4/5","ekstra":[]},{"id":"M5B-6.75","bok":"6.75 a-c","side":"62","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":1,"figur":true,"ferdighet":"Finne hvor stor del av kulene som har en farge","q":"Det er 12 kuler: 5 gule, 4 røde og 3 grønne. Hvor stor del er a) gule b) røde c) grønne?","a":"a) 5/12. b) 4/12. c) 3/12","ekstra":[]},{"id":"M5B-6.76","bok":"6.76","side":"62","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Åpen utforsking","niva":2,"figur":true,"ferdighet":"Tegne like figurer og fargelegge samme brøkdel på ulike måter","q":"Tegn to like rektangler. Fargelegg 1/3 av hvert på forskjellige måter.","a":"Åpen. Del i 6 ruter og farg 2 ruter, f.eks. to striper øverst i det ene og to striper nederst i det andre.","ekstra":[]},{"id":"M5B-6.77","bok":"6.77 a-d","side":"62","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Tegne hele figuren når en del er gitt","q":"Delen er a) 2 ruter og 1/3 b) 3 ruter og 1/4 c) 5 ruter og 1/2. Hvor mange ruter er hele figuren?","a":"a) 6. b) 12. c) 10","ekstra":[]},{"id":"M5B-6.78","bok":"6.78","side":"62","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Doble teller og nevner for å lage ny brøk","q":"Skriv en ny brøk der teller og nevner er dobbelt så store som i 3/5.","a":"6/10","ekstra":[]},{"id":"M5B-6.79","bok":"6.79 a-d","side":"62","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Sette <, > eller = mellom brøker og regnestykker","q":"Skriv riktig tegn. a) 2/3 og 4/6 b) 1/4 og 1/5 c) 2/7 + 3/7 og 1 d) 7/9 - 2/9 og 5/9","a":"a) =. b) >. c) <. d) =","ekstra":[]},{"id":"M5B-6.80","bok":"6.80 a-d","side":"63","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Finne figurer der 3/4 er fargelagt","q":"Fire figurer er delt i 8 like deler. Antall fargelagte deler: A 6, B 5, C 6, D 3. Hvilke har 3/4 fargelagt?","a":"A og C (6/8 = 3/4)","ekstra":[]},{"id":"M5B-6.81","bok":"6.81 a-d","side":"63","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Tegne hele figuren når en del er gitt","q":"Delen er a) 2 ruter og 1/5 b) 4 ruter og 2/3 c) 3 ruter og 3/4. Hvor mange ruter er hele figuren?","a":"a) 10. b) 6. c) 4","ekstra":[]},{"id":"M5B-6.82","bok":"6.82 a-c","side":"63","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Mønster og logikk","niva":2,"figur":false,"ferdighet":"Skrive ulike brøker som oppfyller en betingelse","q":"Skriv to ulike brøker a) der telleren er 3 mindre enn nevneren b) der telleren er halvparten av nevneren c) som har samme verdi som 3/4.","a":"F.eks. a) 1/4 og 2/5. b) 2/4 og 3/6. c) 6/8 og 9/12","ekstra":[]},{"id":"M5B-6.83","bok":"6.83 a-d","side":"63","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Lese av brøk der piler A og B peker på tallinja","q":"Fire tallinjer fra 0 til 1 er delt i tideler. Pil A og B står på a) 3. og 8. strek b) 1. og 5. strek c) 2. og 9. strek. Hvilke brøker peker pilene på?","a":"a) 3/10 og 8/10. b) 1/10 og 5/10. c) 2/10 og 9/10","ekstra":[]},{"id":"M5B-6.84","bok":"6.84 a-b","side":"64","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Regne ut hvor stor del av figuren som er fargelagt","q":"a) En stripe er delt i 5 deler: 2 blå, 1 gul og 2 hvite. Regn ut blå + gul. b) En sirkel er delt i 8: 3 røde, 2 blå og 3 hvite. Regn ut røde + blå.","a":"a) 2/5 + 1/5 = 3/5. b) 3/8 + 2/8 = 5/8","ekstra":[]},{"id":"M5B-6.85","bok":"6.85 a-c","side":"64","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Regne ut sum og differanse av brøker med lik nevner","q":"Regn ut. a) 3/7 + 2/7 b) 5/12 + 4/12 c) 11/15 - 6/15 d) 18/20 - 9/20","a":"a) 5/7. b) 9/12. c) 5/15. d) 9/20","ekstra":[]},{"id":"M5B-6.86","bok":"6.86 a-c","side":"64","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Ferdighetstrening","niva":3,"figur":false,"ferdighet":"Regne med tre ledd og blandede tall","q":"Regn ut. a) 2/5 + 1/5 + 1/5 b) 7/12 + 3/12 - 4/12 c) 1 2/5 - 4/5","a":"a) 4/5. b) 6/12. c) 7/5 - 4/5 = 3/5","ekstra":[]},{"id":"M5B-6.87","bok":"6.87","side":"64","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Fargelegge ulike brøkdeler av en pyramide med ti ruter","q":"Tegn en pyramide med 10 ruter (1, 2, 3 og 4 ruter i rader). Fargelegg 3/10 rødt, 1/2 gult og 1/5 blått.","a":"3 røde, 5 gule og 2 blå ruter (3 + 5 + 2 = 10)","ekstra":[]},{"id":"M5B-6.88","bok":"6.88","side":"65","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Tekstoppgave","niva":3,"figur":true,"ferdighet":"Regne ut hvor stor del av en pizza som er igjen etter at fem har spist biter","q":"Fem barn deler pizza. Hver pizza er delt i 8 like store biter. De spiser 3, 5, 4, 6 og 2 biter. De hadde kjøpt tre hele pizzaer. Hvor stor del av den siste pizzaen er igjen?","a":"3 + 5 + 4 + 6 + 2 = 20 biter spist. 3 · 8 = 24 biter. 4 biter er igjen = 4/8 av siste pizza","ekstra":[]},{"id":"M5B-6.89","bok":"6.89 a-d","side":"65","kap":6,"tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","type":"Tolk data","niva":3,"figur":true,"ferdighet":"Lese søylediagram og skrive brøk av antall elever","q":"Et søylediagram viser antall søsken hos 20 elever: 0 søsken 4, 1 søsken 9, 2 søsken 5, 3 søsken 2. Hvor stor del av elevene har a) 0 søsken b) 1 søsken c) flere enn 1 søsken d) færre enn 3 søsken?","a":"a) 4/20. b) 9/20. c) (5 + 2)/20 = 7/20. d) (4 + 9 + 5)/20 = 18/20","ekstra":[]},{"id":"M5B-SPILL-S67","bok":"Spill: Fire på rad","side":"67","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Spill / aktivitet","niva":1,"figur":true,"ferdighet":"Øve gangetabellen ved å finne produkter av to tall 1-9 på et spillebrett","q":"Lag et eget spillebrett med 12 produkter fra gangetabellen. Spiller 1 legger en binders på ett av tallene 1-9, spiller 2 på et annet tall. Gang tallene sammen og dekk produktet på brettet. Første med 4 på rad vinner. Hva dekker du hvis tallene er 6 og 7?","a":"6 · 7 = 42. Ingen fasit ellers; spill.","ekstra":[]},{"id":"M5B-7.1","bok":"7.1 a-c","side":"68","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Ferdighetstrening","niva":1,"figur":true,"ferdighet":"Skrive gjentatt addisjon som gangestykke og regne ut","q":"Det er 6 passasjerer i hver buss. Hvor mange passasjerer er det i a) 3 busser b) 7 busser c) 10 busser? Skriv som gangestykke.","a":"a) 3 · 6 = 18. b) 7 · 6 = 42. c) 10 · 6 = 60","ekstra":[]},{"id":"M5B-7.2","bok":"7.2 a-c","side":"68","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Ferdighetstrening","niva":1,"figur":true,"ferdighet":"Bruke hopp på tallinje til å finne produkt","q":"En gresshoppe hopper 4 cm per hopp. Hvor langt har den hoppet etter a) 3 hopp b) 6 hopp c) 9 hopp? Skriv som gangestykke.","a":"a) 3 · 4 = 12 cm. b) 6 · 4 = 24 cm. c) 9 · 4 = 36 cm","ekstra":[]},{"id":"M5B-7.3","bok":"7.3 a-i","side":"69","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Ferdighetstrening","niva":1,"figur":true,"ferdighet":"Finne ukjent faktor i 5 · ? = produkt (5-gangen) fra tårn","q":"Hvert tårn består av 5 klosser. Tårnenes høyder: a) 30 cm b) 45 cm c) 35 cm d) 50 cm e) 20 cm. Hvor høy er hver kloss? Skriv som gangestykke.","a":"a) 5 · 6 = 30, 6 cm. b) 5 · 9 = 45, 9 cm. c) 5 · 7 = 35, 7 cm. d) 5 · 10 = 50, 10 cm. e) 5 · 4 = 20, 4 cm","ekstra":[]},{"id":"M5B-7.4","bok":"7.4 a-b","side":"69","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Tegne rutenett og fylle ut manglende produkter","q":"Tegn rutenettet og fyll ut. Kolonner: 2, 5, 8. Rader: 3, 6.","a":"Rad 3: 6, 15, 24. Rad 6: 12, 30, 48","ekstra":[]},{"id":"M5B-7.5","bok":"7.5 a-b","side":"70","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Ferdighetstrening","niva":1,"figur":true,"ferdighet":"Fylle ut tabeller med halvparten og dobbelt av tall","q":"Fyll ut tabellene. a) Tall: 12, 30, 46, 100. Finn halvparten og dobbelt av hvert tall. b) Dobbelt er gitt: 18, 40, 76, 150. Finn tallet som er halvparten av dobbelt-verdien.","a":"a) 12: halvparten 6, dobbelt 24. 30: 15 og 60. 46: 23 og 92. 100: 50 og 200. b) 18 → 9. 40 → 20. 76 → 38. 150 → 75","ekstra":[]},{"id":"M5B-7.6","bok":"7.6 a-c","side":"70","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Mønster og logikk","niva":1,"figur":false,"ferdighet":"Finne regelen i en tallfølge og fortsette den med fire tall","q":"Hvilke fire tall kommer videre i tallfølgen? a) 3, 7, 11, 15, … b) 50, 45, 40, 35, … c) 5, 12, 19, 26, …","a":"a) +4: 19, 23, 27, 31. b) −5: 30, 25, 20, 15. c) +7: 33, 40, 47, 54","ekstra":[]},{"id":"M5B-7.7","bok":"7.7 a-c","side":"70","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Mønster og logikk","niva":2,"figur":false,"ferdighet":"Finne regelen i en tallfølge med større hopp og fortsette den","q":"Hvilke fire tall kommer videre i tallfølgen? a) 21, 26, 31, 36, … b) 15, 23, 31, 39, … c) 200, 211, 222, 233, …","a":"a) +5: 41, 46, 51, 56. b) +8: 47, 55, 63, 71. c) +11: 244, 255, 266, 277","ekstra":[]},{"id":"M5B-7.8","bok":"7.8","side":"70","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Åpen utforsking","niva":2,"figur":false,"ferdighet":"Lage egne tallmønstre og la en annen elev fortsette dem","q":"Lag din egen tallfølge med minst fem tall. Bytt med sidemannen, som skal finne regelen og skrive de tre neste tallene.","a":"Åpen. Eksempel: start 5, legg til 3 hver gang: 5, 8, 11, 14, 17 → neste tall er 20, 23, 26","ekstra":[]},{"id":"M5B-S71-Faktorer-i-full-fart","bok":"Spill s. 71 «Faktorer i full fart»","side":"71","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Spill / aktivitet","niva":2,"figur":true,"ferdighet":"Finne alle faktorpar til et tall på et tallbrett (1-30)","q":"Spill for to. Tallbrett 1-30. Spiller 1 velger et tall, og spiller 2 finner alle faktorene i tallet. Eksempel for øving: finn alle faktorpar til 18 og til 24.","a":"18: 1·18, 2·9, 3·6. 24: 1·24, 2·12, 3·8, 4·6","ekstra":[]},{"id":"M5B-7.9","bok":"7.9","side":"72","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Tekstoppgave","niva":1,"figur":true,"ferdighet":"Bruke multiplikasjon i en enkel hverdagssituasjon","q":"Ola kjøper sju appelsiner. De koster tre kroner stykket. Hva må han betale?","a":"7 · 3 = 21 kroner","ekstra":[]},{"id":"M5B-7.10","bok":"7.10","side":"72","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Tekstoppgave","niva":1,"figur":true,"ferdighet":"Bruke multiplikasjon i en enkel hverdagssituasjon","q":"Lena kjøper fire bananer til åtte kroner stykket. Hva må hun betale?","a":"4 · 8 = 32 kroner","ekstra":[]},{"id":"M5B-7.11","bok":"7.11","side":"72","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Tekstoppgave","niva":1,"figur":true,"ferdighet":"Bruke multiplikasjon i en enkel hverdagssituasjon","q":"I en eske er det åtte blyanter. Hvor mange blyanter er det i fem esker?","a":"5 · 8 = 40 blyanter","ekstra":[]},{"id":"M5B-7.12","bok":"7.12","side":"72","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Tekstoppgave","niva":1,"figur":true,"ferdighet":"Bruke multiplikasjon i en enkel hverdagssituasjon","q":"Karim har seks poser med klistremerker. Det er ti klistremerker i hver pose. Hvor mange klistremerker har han?","a":"6 · 10 = 60 klistremerker","ekstra":[]},{"id":"M5B-7.13","bok":"7.13","side":"72","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Tekstoppgave","niva":1,"figur":true,"ferdighet":"Bruke multiplikasjon i en enkel hverdagssituasjon","q":"Fem venner spleiser på en gave. Hver må betale åtte kroner. Hva koster gaven?","a":"5 · 8 = 40 kroner","ekstra":[]},{"id":"M5B-7.14","bok":"7.14","side":"72","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Tekstoppgave","niva":1,"figur":true,"ferdighet":"Bruke multiplikasjon i en enkel hverdagssituasjon","q":"En edderkopp har åtte bein. Hvor mange bein har sju edderkopper?","a":"7 · 8 = 56 bein","ekstra":[]},{"id":"M5B-7.15","bok":"7.15 a-c","side":"73","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Gange med 10, 100 og hele tiere/hundrer","q":"Regn ut. a) 6 · 10, 10 · 8, 5 · 10 b) 4 · 20, 20 · 7, 9 · 30 c) 100 · 6, 12 · 100, 9 · 200","a":"a) 6 · 10 = 60, 10 · 8 = 80, 5 · 10 = 50 b) 4 · 20 = 80, 20 · 7 = 140, 9 · 30 = 270 c) 100 · 6 = 600, 12 · 100 = 1200, 9 · 200 = 1800","ekstra":[]},{"id":"M5B-7.16","bok":"7.16 a-c","side":"73","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Gange med tiere, femtiere og hundrer","q":"Regn ut. a) 8 · 10, 15 · 10, 10 · 21 b) 6 · 30, 4 · 50, 70 · 3 c) 3 · 300, 600 · 4, 5 · 800","a":"a) 8 · 10 = 80, 15 · 10 = 150, 10 · 21 = 210 b) 6 · 30 = 180, 4 · 50 = 200, 70 · 3 = 210 c) 3 · 300 = 900, 600 · 4 = 2400, 5 · 800 = 4000","ekstra":[]},{"id":"M5B-7.17","bok":"7.17 a-c","side":"73","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Gange store runde tall med ensifrede tall","q":"Regn ut. a) 7 · 60, 30 · 8, 9 · 50 b) 4 · 300, 200 · 9, 600 · 5 c) 1000 · 6, 3000 · 5, 8000 · 4","a":"a) 7 · 60 = 420, 30 · 8 = 240, 9 · 50 = 450 b) 4 · 300 = 1200, 200 · 9 = 1800, 600 · 5 = 3000 c) 1000 · 6 = 6000, 3000 · 5 = 15000, 8000 · 4 = 32000","ekstra":[]},{"id":"M5B-7.18","bok":"7.18 a-c","side":"73","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Åpen utforsking","niva":3,"figur":false,"ferdighet":"Lage flere gangestykker med samme produkt, også med tosifrede tall","q":"Lag minst fire gangestykker der svaret blir a) 90 b) 240 c) 600.","a":"Eksempler. a) 9·10, 3·30, 6·15, 5·18, 2·45. b) 24·10, 12·20, 6·40, 8·30, 4·60. c) 6·100, 2·300, 3·200, 20·30, 5·120","ekstra":[]},{"id":"M5B-7.19","bok":"7.19 a-c","side":"73","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Finne manglende faktor i gangestykker med tiere og hundrer","q":"Gjør ferdig gangestykkene. a) 7·□=70, □·5=300, □·6=120, 8·□=240. b) □·100=900, □·100=2000, 4·□=400, 6·□=1800. c) □·4=800, 5·□=3000, 9·□=900, 12·□=1200.","a":"a) 10, 60, 20, 30. b) 9, 20, 100, 300. c) 200, 600, 100, 100","ekstra":[]},{"id":"M5B-7.20","bok":"7.20 a-d","side":"74","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon på regneark","type":"Digital oppgave","niva":3,"figur":true,"ferdighet":"Lage et regneark med formler for pris · antall og sum, og endre verdier","q":"Skolekafé for 10 elever. a) Lag et regneark med kolonnene vare, pris, antall og å betale: saft 7 kr, boller 12 kr, frukt 5 kr, 10 av hver. Bruk formler (f.eks. =B3*C3) og SUM. Hva blir summen? b) Hva blir summen hvis bollene koster 15 kr? c) Hva blir summen hvis det bare er 8 elever (med opprinnelige priser)? d) Frukt koster nå p kr. Hvor høy kan prisen p (hele kroner) være hvis summen ikke skal være over 300 kr for 10 elever (saft og boller som i a)?","a":"a) 70 + 120 + 50 = 240 kr. b) 70 + 150 + 50 = 270 kr. c) 56 + 96 + 40 = 192 kr. d) 70 + 120 = 190; 300 − 190 = 110; 110 : 10 = 11. Maks 11 kr per frukt","ekstra":[]},{"id":"M5B-7.21","bok":"7.21","side":"74","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon på regneark","type":"Digital oppgave","niva":3,"figur":true,"ferdighet":"Lage regneark med priser med desimaler og regne ut flere like kjøp","q":"Lag et regneark der du bruker disse varene og prisene: 12,50 kr, 8,90 kr, 15,20 kr, 6,40 kr. Du skal kjøpe 3 av hver. Regn ut pris per vare og totalsummen.","a":"37,50 + 26,70 + 45,60 + 19,20 = 129,00 kr","ekstra":[]},{"id":"M5B-S75-Regneark-til-tusen","bok":"Spill s. 75 «Regneark til tusen»","side":"75","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon på regneark","type":"Spill / aktivitet","niva":3,"figur":true,"ferdighet":"Bruke formler i regneark og planlegge tall for å nå et mål","q":"Regnearket har tallene 25, 50 og 100 i kolonne A og tall i kolonne B. Kolonne C er A · B og summen står under. Hvilke tall kan du skrive i kolonne B for at summen blir nøyaktig 1000?","a":"Flere løsninger. Eksempel: B = 4, 6, 6: 100 + 300 + 600 = 1000","ekstra":[]},{"id":"M5B-7.22","bok":"7.22 a-f","side":"76","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon på rutenett og tosifrede tall","type":"Visuell oppgave","niva":1,"figur":true,"ferdighet":"Finne antall ruter i rutenett og skrive som gangestykke","q":"Hvor mange ruter er det? Skriv som gangestykke. Rutenett: a) 3 · 7 b) 5 · 5 c) 8 · 3 d) 9 · 2 (bredde · høyde).","a":"a) 3 · 7 = 21. b) 5 · 5 = 25. c) 8 · 3 = 24. d) 9 · 2 = 18","ekstra":[]},{"id":"M5B-7.23","bok":"7.23 a-d","side":"77","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon på rutenett og tosifrede tall","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Dele opp et stort rutenett i tiere og enere og regne ut","q":"Hvordan vil du finne antall ruter? Rutenett: a) 12 ruter lang og 6 høy b) 14 lang og 5 høy c) 13 lang og 7 høy d) 16 lang og 4 høy. Tips: del opp.","a":"a) 10·6 + 2·6 = 60 + 12 = 72. b) 10·5 + 4·5 = 50 + 20 = 70. c) 10·7 + 3·7 = 70 + 21 = 91. d) 10·4 + 6·4 = 40 + 24 = 64","ekstra":[]},{"id":"M5B-7.24","bok":"7.24 a-d","side":"78","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon på rutenett og tosifrede tall","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Gange tosifret med ensifret tall ved å dele opp i tiere og enere","q":"Regn ut. a) 14 · 6, 18 · 5, 17 · 4, 12 · 8","a":"a) 14 · 6 = 84, 18 · 5 = 90, 17 · 4 = 68, 12 · 8 = 96","ekstra":[]},{"id":"M5B-7.25","bok":"7.25 a-d","side":"79","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon på rutenett og tosifrede tall","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Gange tosifret tall (10-19) med ensifret tall","q":"Regn ut. a) 15 · 6, 13 · 8, 16 · 5 b) 14 · 7, 19 · 3, 17 · 6 c) 18 · 9, 16 · 4, 12 · 9 d) 11 · 7, 15 · 8, 19 · 5","a":"a) 15 · 6 = 90, 13 · 8 = 104, 16 · 5 = 80 b) 14 · 7 = 98, 19 · 3 = 57, 17 · 6 = 102 c) 18 · 9 = 162, 16 · 4 = 64, 12 · 9 = 108 d) 11 · 7 = 77, 15 · 8 = 120, 19 · 5 = 95","ekstra":[]},{"id":"M5B-7.26","bok":"7.26 a-d","side":"79","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon på rutenett og tosifrede tall","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Gange tosifret tall (20-50) med ensifret tall","q":"Regn ut. a) 23 · 4, 41 · 5, 32 · 3 b) 24 · 6, 52 · 3, 35 · 4 c) 42 · 5, 33 · 6, 47 · 2 d) 51 · 6, 34 · 5, 29 · 4","a":"a) 23 · 4 = 92, 41 · 5 = 205, 32 · 3 = 96 b) 24 · 6 = 144, 52 · 3 = 156, 35 · 4 = 140 c) 42 · 5 = 210, 33 · 6 = 198, 47 · 2 = 94 d) 51 · 6 = 306, 34 · 5 = 170, 29 · 4 = 116","ekstra":[]},{"id":"M5B-7.27","bok":"7.27 a-c","side":"80","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon på rutenett og tosifrede tall","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Gange tosifret med ensifret tall (repetisjon)","q":"Regn ut. a) 22 · 6, 34 · 5 b) 27 · 4, 43 · 6 c) 35 · 7, 52 · 8","a":"a) 22 · 6 = 132, 34 · 5 = 170 b) 27 · 4 = 108, 43 · 6 = 258 c) 35 · 7 = 245, 52 · 8 = 416","ekstra":[]},{"id":"M5B-7.28","bok":"7.28 a-c","side":"80","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon på rutenett og tosifrede tall","type":"Visuell oppgave","niva":3,"figur":true,"ferdighet":"Dele opp et stort rutenett i fire deler og regne ut antall ruter","q":"Hvor mange ruter er det? Del opp og regn ut. a) rutenett 15 · 12 b) 13 · 14 c) 18 · 16.","a":"a) 10·10 + 10·2 + 5·10 + 5·2 = 100 + 20 + 50 + 10 = 180. b) 100 + 40 + 30 + 12 = 182. c) 100 + 60 + 80 + 48 = 288","ekstra":[]},{"id":"M5B-7.29","bok":"7.29 a-d","side":"81","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon på rutenett og tosifrede tall","type":"Ferdighetstrening","niva":3,"figur":true,"ferdighet":"Tegne rutenett og regne ut tosifret · tosifret","q":"Tegn rutenett og regn ut. a) 13 · 15 b) 14 · 16 c) 12 · 12 d) 21 · 13","a":"a) 13·15 = 195. b) 14·16 = 224. c) 12·12 = 144. d) 21·13 = 273","ekstra":[]},{"id":"M5B-7.30","bok":"7.30 a-d","side":"81","kap":7,"tema":"Tall og regning","emne":"Multiplikasjon på rutenett og tosifrede tall","type":"Ferdighetstrening","niva":3,"figur":false,"ferdighet":"Gange tosifret · tosifret med egen valgt metode","q":"Regn på den måten du vil. a) 25 · 11 b) 43 · 11 c) 18 · 13 d) 27 · 14","a":"a) 275. b) 473. c) 234. d) 378","ekstra":[]},{"id":"M5B-7.31","bok":"7.31 a-f","side":"82","kap":7,"tema":"Tall og regning","emne":"Divisjon og delestykker","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Finne skjult tall i en gangetrekant og skrive som gangestykke","q":"Hvilket tall er skjult? Skriv som gangestykke. Trekant a) faktorene 4 og 9 b) toppen 56 og én faktor 7 c) toppen 45 og én faktor 5 d) faktorene 6 og 7 e) toppen 72 og én faktor 8 f) toppen 81 og én faktor 9.","a":"a) 4 · 9 = 36. b) 8 · 7 = 56 (skjult 8). c) 9 · 5 = 45 (skjult 9). d) 6 · 7 = 42. e) 9 · 8 = 72 (skjult 9). f) 9 · 9 = 81 (skjult 9)","ekstra":[]},{"id":"M5B-7.32","bok":"7.32 a-c","side":"83","kap":7,"tema":"Tall og regning","emne":"Divisjon og delestykker","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Regne ut enkle delestykker","q":"Regn ut. a) 18 : 3, 20 : 4 b) 14 : 2, 36 : 4 c) 24 : 3, 27 : 9","a":"a) 18 : 3 = 6, 20 : 4 = 5 b) 14 : 2 = 7, 36 : 4 = 9 c) 24 : 3 = 8, 27 : 9 = 3","ekstra":[]},{"id":"M5B-7.33","bok":"7.33 a-c","side":"83","kap":7,"tema":"Tall og regning","emne":"Divisjon og delestykker","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Regne ut delestykker med 4, 5 og 6","q":"Regn ut. a) 24 : 4, 36 : 4 b) 20 : 5, 35 : 5 c) 30 : 6, 54 : 6","a":"a) 24 : 4 = 6, 36 : 4 = 9 b) 20 : 5 = 4, 35 : 5 = 7 c) 30 : 6 = 5, 54 : 6 = 9","ekstra":[]},{"id":"M5B-7.34","bok":"7.34 a-c","side":"83","kap":7,"tema":"Tall og regning","emne":"Divisjon og delestykker","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Regne ut delestykker med 6, 7, 8 og 9","q":"Regn ut. a) 42 : 6, 54 : 6 b) 56 : 8, 63 : 9 c) 49 : 7, 72 : 8","a":"a) 42 : 6 = 7, 54 : 6 = 9 b) 56 : 8 = 7, 63 : 9 = 7 c) 49 : 7 = 7, 72 : 8 = 9","ekstra":[]},{"id":"M5B-7.35","bok":"7.35 a-b","side":"83","kap":7,"tema":"Tall og regning","emne":"Divisjon og delestykker","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Fylle ut tabeller med dele- og gangeregel","q":"Skriv av tabellene og gjør dem ferdige. a) Regel : 3. Inn: 12, 15, 24, 30, 60. b) Regel : 10. Inn: 30, 50, 80, 120, 200.","a":"a) 4, 5, 8, 10, 20. b) 3, 5, 8, 12, 20","ekstra":[]},{"id":"M5B-7.36","bok":"7.36 a-d","side":"83","kap":7,"tema":"Tall og regning","emne":"Divisjon og delestykker","type":"Åpen utforsking","niva":3,"figur":false,"ferdighet":"Lage flere delestykker med samme kvotient","q":"Lag minst tre delestykker der svaret blir a) 6 b) 7 c) 8 d) 9.","a":"Eksempler. a) 12:2, 18:3, 24:4, 30:5, 36:6, 60:10. b) 14:2, 21:3, 28:4, 35:5, 49:7. c) 16:2, 24:3, 32:4, 40:5, 56:7. d) 18:2, 27:3, 36:4, 45:5, 63:7","ekstra":[]},{"id":"M5B-S82-Gange-eller-dele","bok":"Spill s. 82 «Gange eller dele!»","side":"82","kap":7,"tema":"Tall og regning","emne":"Divisjon og delestykker","type":"Spill / aktivitet","niva":2,"figur":true,"ferdighet":"Regne ut skjult tall i en gangetrekant (gange eller dele)","q":"Spill i gruppe. En gangetrekant har toppen 48. Én faktor er 6, og den andre er skjult. Spilleren må finne den skjulte faktoren. Prøv også: faktorene 7 og 9 er synlige, toppen er skjult.","a":"48 : 6 = 8. Skjult faktor er 8. Faktorene 7 og 9 gir toppen 7 · 9 = 63","ekstra":[]},{"id":"M5B-7.37","bok":"7.37 a-d","side":"84","kap":7,"tema":"Tall og regning","emne":"Divisjon og delestykker","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Finne manglende tall i gange- og delestykker som hører sammen","q":"Hvilke tall mangler? Fyll ut regnefamilien. a) □ · 4 = 20 og 20 : 4 = □ b) □ · 3 = 21 og 21 : 3 = □ c) 6 · □ = 48 og 48 : 6 = □ d) 7 · □ = 56 og 56 : 7 = □","a":"a) 5 og 5. b) 7 og 7. c) 8 og 8. d) 8 og 8","ekstra":[]},{"id":"M5B-7.38","bok":"7.38 a-f","side":"84","kap":7,"tema":"Tall og regning","emne":"Divisjon og delestykker","type":"Tekstoppgave","niva":2,"figur":true,"ferdighet":"Dele et antall klosser i like tårn og skrive delestykket","q":"Hvor mange tårn kan du lage? a) 24 klosser, 6 per tårn b) 36 med 4 c) 40 med 5 d) 28 med 7 e) 54 med 9 f) 72 med 8. Skriv som delestykke.","a":"a) 24 : 6 = 4. b) 36 : 4 = 9. c) 40 : 5 = 8. d) 28 : 7 = 4. e) 54 : 9 = 6. f) 72 : 8 = 9","ekstra":[]},{"id":"M5B-7.39","bok":"7.39 a-c","side":"85","kap":7,"tema":"Tall og regning","emne":"Divisjon og delestykker","type":"Tekstoppgave","niva":3,"figur":false,"ferdighet":"Bruke gjentatt subtraksjon og divisjon med rest i en tekstoppgave","q":"Nora skal kutte opp et tau på 25 m i snorer som hver er 4 m lange. a) Hvor mye tau er igjen når hun har tatt av til 2 snorer? Til 4 snorer? b) Hvor mange snorer på 4 m kan hun lage av tauet? c) Hvor mye tau er igjen da?","a":"a) 25 − 8 = 17 m. 25 − 16 = 9 m. b) 25 : 4 = 6 rest 1, så 6 snorer. c) 1 m","ekstra":[]},{"id":"M5B-7.40","bok":"7.40 a-d","side":"85","kap":7,"tema":"Tall og regning","emne":"Divisjon og delestykker","type":"Tekstoppgave","niva":2,"figur":true,"ferdighet":"Dele en lengde i like deler på 4 m og finne antall og rest","q":"Hvor mange snorer på 4 m kan vi lage av a) 16 m, b) 22 m, c) 30 m, d) 41 m?","a":"a) 16 : 4 = 4. b) 22 : 4 = 5 rest 2. c) 30 : 4 = 7 rest 2. d) 41 : 4 = 10 rest 1","ekstra":[]},{"id":"M5B-7.41","bok":"7.41 a-d","side":"85","kap":7,"tema":"Tall og regning","emne":"Divisjon og delestykker","type":"Tekstoppgave","niva":3,"figur":true,"ferdighet":"Dele en lengde i like deler på 8 m og finne antall og rest","q":"Hvor mange snorer på 8 m kan vi lage av a) 24 m, b) 30 m, c) 50 m, d) 75 m?","a":"a) 24 : 8 = 3. b) 30 : 8 = 3 rest 6. c) 50 : 8 = 6 rest 2. d) 75 : 8 = 9 rest 3","ekstra":[]},{"id":"M5B-7.42","bok":"7.42 a-d","side":"85","kap":7,"tema":"Tall og regning","emne":"Divisjon og delestykker","type":"Tekstoppgave","niva":3,"figur":true,"ferdighet":"Dele en lengde i like deler på 9 m og finne antall og rest","q":"Hvor mange snorer på 9 m kan vi lage av a) 27 m, b) 40 m, c) 63 m, d) 80 m?","a":"a) 27 : 9 = 3. b) 40 : 9 = 4 rest 4. c) 63 : 9 = 7. d) 80 : 9 = 8 rest 8","ekstra":[]},{"id":"M5B-7.43","bok":"7.43 a-b","side":"86","kap":7,"tema":"Tall og regning","emne":"Divisjon og delestykker","type":"Spill / aktivitet","niva":3,"figur":true,"ferdighet":"Lage tosifrede tall med kort og bruke dem i delestykker","q":"Du har røde kort 3 og 6 og svarte kort 2, 4 og 9. Sett de røde kortene sammen til 36 eller 63. a) Lag delestykker der du deler tallet på et svart kort. b) Hvilke svar får du når du bruker 36?","a":"a) 36 : 2 = 18, 36 : 4 = 9, 36 : 9 = 4, 63 : 9 = 7 (63 går ikke opp i 2 eller 4). b) 18, 9 og 4","ekstra":[]},{"id":"M5B-7.44","bok":"7.44 a-d","side":"86","kap":7,"tema":"Tall og regning","emne":"Divisjon og delestykker","type":"Tekstoppgave","niva":2,"figur":false,"ferdighet":"Dele en kortstokk likt og finne rest","q":"Det er 36 kort i en bunke. Hvor mange blir det på hver når kortene deles på a) 2 personer b) 4 personer c) 5 personer d) 7 personer?","a":"a) 18. b) 9. c) 7 rest 1. d) 5 rest 1","ekstra":[]},{"id":"M5B-7.45","bok":"7.45","side":"87","kap":7,"tema":"Tall og regning","emne":"Tekstoppgaver og divisjon med større tall","type":"Tekstoppgave","niva":2,"figur":true,"ferdighet":"Finne antall ved å dele en sum på pris per enhet","q":"Mille må tjene 72 kr på å selge limonade. Hun tar 6 kr per glass. Hvor mange glass må hun selge?","a":"72 : 6 = 12 glass","ekstra":[]},{"id":"M5B-7.46","bok":"7.46 a-d","side":"87","kap":7,"tema":"Tall og regning","emne":"Tekstoppgaver og divisjon med større tall","type":"Tekstoppgave","niva":3,"figur":true,"ferdighet":"Bruke både gange og dele i en situasjon med flere spørsmål","q":"Åtte barn drar på fornøyelsespark og betaler 96 kr for å komme inn. a) Hvor mye betaler hvert barn? b) Inne i parken kjøper de åtte barna en is hver til 7 kr. Hva koster det til sammen? c) Seks av barna prøver ballkasting. De betaler 12 kr hver. Hva betaler de til sammen? d) Sju barn kjøper hver en brus. De betaler 63 kr til sammen. Hva koster én brus?","a":"a) 96 : 8 = 12 kr. b) 8 · 7 = 56 kr. c) 6 · 12 = 72 kr. d) 63 : 7 = 9 kr","ekstra":[]},{"id":"M5B-7.47","bok":"7.47","side":"88","kap":7,"tema":"Tall og regning","emne":"Tekstoppgaver og divisjon med større tall","type":"Tekstoppgave","niva":3,"figur":true,"ferdighet":"Dele en sum penger likt på flere personer","q":"Fire barn hjelper naboene sine og får 248 kr til sammen. De deler pengene likt. Hvor mye får hver?","a":"248 : 4 = 62 kr","ekstra":[]},{"id":"M5B-7.48","bok":"7.48","side":"88","kap":7,"tema":"Tall og regning","emne":"Tekstoppgaver og divisjon med større tall","type":"Tekstoppgave","niva":3,"figur":false,"ferdighet":"Dele en sum penger likt","q":"Tre barn skal dele 219 kr. Hvor mye får hver av dem?","a":"219 : 3 = 73 kr","ekstra":[]},{"id":"M5B-7.49","bok":"7.49 a-c","side":"89","kap":7,"tema":"Tall og regning","emne":"Tekstoppgaver og divisjon med større tall","type":"Tekstoppgave","niva":2,"figur":false,"ferdighet":"Dele opp en gruppe i like grupper","q":"På Furuskolen begynner 84 elever på 6. trinn. Hvor mange elever blir det i hver gruppe hvis elevene deles likt i a) 2 grupper b) 3 grupper c) 4 grupper?","a":"a) 84 : 2 = 42. b) 84 : 3 = 28. c) 84 : 4 = 21","ekstra":[]},{"id":"M5B-7.50","bok":"7.50","side":"89","kap":7,"tema":"Tall og regning","emne":"Tekstoppgaver og divisjon med større tall","type":"Tekstoppgave","niva":3,"figur":true,"ferdighet":"Dele et antall på spillere og tolke resten","q":"Fem ballspillere skal dele 128 ballonger. Hvor mange får hver, og hvor mange blir til overs?","a":"128 : 5 = 25 rest 3. Hver får 25, og 3 blir til overs","ekstra":[]},{"id":"M5B-7.51","bok":"7.51","side":"89","kap":7,"tema":"Tall og regning","emne":"Tekstoppgaver og divisjon med større tall","type":"Tekstoppgave","niva":2,"figur":true,"ferdighet":"Dele et stort antall likt","q":"Fire søsken får 360 frimerker av en tante. De deler likt. Hvor mange får hver?","a":"360 : 4 = 90 frimerker","ekstra":[]},{"id":"M5B-7.52","bok":"7.52","side":"89","kap":7,"tema":"Tall og regning","emne":"Tekstoppgaver og divisjon med større tall","type":"Tekstoppgave","niva":3,"figur":true,"ferdighet":"Dele med rest i en festsituasjon","q":"Julie har med seg 150 smågodt til en fest. Det er sju barn. Hvor mange får hver, og hvor mange er til overs?","a":"150 : 7 = 21 rest 3. Hver får 21, 3 er til overs","ekstra":[]},{"id":"M5B-7.53","bok":"7.53","side":"89","kap":7,"tema":"Tall og regning","emne":"Tekstoppgaver og divisjon med større tall","type":"Tekstoppgave","niva":3,"figur":false,"ferdighet":"Tolke rest i en fordelingsoppgave","q":"På en skole er det 150 barn. De skal reise med fire busser og fordeler seg omtrent likt. Hvor mange blir det i hver buss?","a":"150 : 4 = 37 rest 2. Omtrent 37 per buss (to busser får 38)","ekstra":[]},{"id":"M5B-7.54","bok":"7.54 a-b","side":"89","kap":7,"tema":"Tall og regning","emne":"Tekstoppgaver og divisjon med større tall","type":"Tekstoppgave","niva":3,"figur":false,"ferdighet":"Dele en bok likt på dager og finne startside","q":"En bok er på 240 sider. Eskil vil lese like mange sider hver dag i fire dager. På hvilket sidetall skal han starte å lese a) den andre dagen b) den tredje dagen?","a":"240 : 4 = 60 sider per dag. a) side 61. b) side 121","ekstra":[]},{"id":"M5B-7.55","bok":"7.55 a-e","side":"90","kap":7,"tema":"Tall og regning","emne":"Tekstoppgaver og divisjon med større tall","type":"Tekstoppgave","niva":3,"figur":true,"ferdighet":"Bruke gange, minus og dele (med rest) i en flertrinns tekstoppgave","q":"Nora har kjøpt en tank på 500 liter. Hun fyller den med ei 5-litersbøtte. a) Hvor mange liter har hun fylt etter 12 bøtter? b) Hvor mange liter mangler da? c) Nora bytter til ei bøtte på 8 liter. Hvor mange bøtter må hun helle oppi i alt for å fylle tanken?","a":"a) 12 · 5 = 60 liter. b) 500 − 60 = 440 liter. c) 500 : 8 = 62 rest 4, så hun må helle 63 bøtter (siste ikke helt full)","ekstra":[]},{"id":"M5B-7.56","bok":"7.56 a-c","side":"90","kap":7,"tema":"Tall og regning","emne":"Tekstoppgaver og divisjon med større tall","type":"Tekstoppgave","niva":3,"figur":true,"ferdighet":"Bruke gange, minus og dele i en flertrinns tekstoppgave","q":"Aksel har en tank med plass til 900 liter vann. Han bruker ei 15-litersbøtte. a) Hvor mange liter har han etter 25 bøtter? b) Hvor mange liter mangler da? c) Hvor mange bøtter må han helle oppi i alt for å fylle tanken?","a":"a) 25 · 15 = 375 liter. b) 900 − 375 = 525 liter. c) 900 : 15 = 60 bøtter","ekstra":[]},{"id":"M5B-Prove7-1","bok":"Prøve 1 a-c","side":"92","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Gangetabellen","q":"Regn ut. a) 4 · 3, 8 · 2, 6 · 4, 5 · 3 b) 6 · 5, 7 · 4, 9 · 6, 10 · 8 c) 8 · 5, 6 · 7, 9 · 4, 7 · 9","a":"a) 4 · 3 = 12, 8 · 2 = 16, 6 · 4 = 24, 5 · 3 = 15 b) 6 · 5 = 30, 7 · 4 = 28, 9 · 6 = 54, 10 · 8 = 80 c) 8 · 5 = 40, 6 · 7 = 42, 9 · 4 = 36, 7 · 9 = 63","ekstra":[]},{"id":"M5B-Prove7-2","bok":"Prøve 2 a-c","side":"92","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Ferdighetstrening","niva":1,"figur":false,"ferdighet":"Delestykker i gangetabellen","q":"Regn ut. a) 14 : 2, 16 : 2, 18 : 3, 20 : 4 b) 27 : 3, 40 : 5, 36 : 6, 80 : 8 c) 35 : 7, 48 : 8, 54 : 9, 72 : 9","a":"a) 14 : 2 = 7, 16 : 2 = 8, 18 : 3 = 6, 20 : 4 = 5 b) 27 : 3 = 9, 40 : 5 = 8, 36 : 6 = 6, 80 : 8 = 10 c) 35 : 7 = 5, 48 : 8 = 6, 54 : 9 = 6, 72 : 9 = 8","ekstra":[]},{"id":"M5B-Prove7-3","bok":"Prøve 3 a-e","side":"92","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Tekstoppgave","niva":2,"figur":true,"ferdighet":"Bruke gange og dele med en prisliste","q":"En blyant koster 7 kr og et viskelær 9 kr. a) Kari kjøper 4 blyanter. Hva betaler hun? b) Per kjøper 6 viskelær. Hva betaler han? c) Hun betaler 63 kr for blyanter. Hvor mange blyanter kjøpte hun? d) Ali kjøper 5 blyanter og 7 viskelær. Hva betaler han? e) Hva koster 15 viskelær?","a":"a) 4 · 7 = 28 kr. b) 6 · 9 = 54 kr. c) 63 : 7 = 9 blyanter. d) 5 · 7 + 7 · 9 = 35 + 63 = 98 kr. e) 15 · 9 = 135 kr","ekstra":[]},{"id":"M5B-Prove7-4","bok":"Prøve 4 a-c","side":"93","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Finne antall ruter som gangestykke","q":"Hvor mange ruter er det? Skriv som gangestykker. a) 4 · 9 b) rutenett 14 lang og 6 høy (del opp) c) rutenett 12 lang og 8 høy (del opp).","a":"a) 4 · 9 = 36. b) 10·6 + 4·6 = 60 + 24 = 84. c) 10·8 + 2·8 = 80 + 16 = 96","ekstra":[]},{"id":"M5B-Prove7-5","bok":"Prøve 5 a-c","side":"93","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Gange tosifret med ensifret tall","q":"Regn ut. a) 13 · 6, 16 · 5, 22 · 9","a":"a) 13 · 6 = 78, 16 · 5 = 80, 22 · 9 = 198","ekstra":[]},{"id":"M5B-Prove7-6","bok":"Prøve 6","side":"93","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Tekstoppgave","niva":2,"figur":false,"ferdighet":"Dele penger likt","q":"Fire barn deler 212 kr. Hvor mye får hvert barn?","a":"212 : 4 = 53 kr","ekstra":[]},{"id":"M5B-Prove7-7","bok":"Prøve 7","side":"93","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Tekstoppgave","niva":2,"figur":true,"ferdighet":"Dele myntene i like stabler og finne antall stabler","q":"Mia har 96 kronestykker. Hun lager stabler med seks i hver. Hvor mange stabler kan hun lage med alle myntene?","a":"96 : 6 = 16 stabler","ekstra":[]},{"id":"M5B-Prove7-8","bok":"Prøve 8 a-c","side":"93","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Dele tosifrede og tresifrede tall","q":"Regn ut. a) 90 : 5, 84 : 6 b) 76 : 4, 96 : 6 c) 128 : 4, 144 : 9","a":"a) 90 : 5 = 18, 84 : 6 = 14 b) 76 : 4 = 19, 96 : 6 = 16 c) 128 : 4 = 32, 144 : 9 = 16","ekstra":[]},{"id":"M5B-7.57","bok":"7.57 a-d","side":"94","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Visuell oppgave","niva":1,"figur":true,"ferdighet":"Finne antall øyne på terninger og skrive som gangestykke","q":"Hvor mange øyne er det? Skriv som gangestykker. a) 4 terninger med 3 øyne b) 6 terninger med 4 øyne c) 5 terninger med 6 øyne d) 7 terninger med 2 øyne.","a":"a) 4 · 3 = 12. b) 6 · 4 = 24. c) 5 · 6 = 30. d) 7 · 2 = 14","ekstra":[]},{"id":"M5B-7.58","bok":"7.58 a-d","side":"94","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Tekstoppgave","niva":1,"figur":true,"ferdighet":"Finne antall hjul på kjøretøy og skrive som gangestykke","q":"Hvor mange hjul er det? Skriv som gangestykker. a) 6 sykler (2 hjul) b) 4 trehjulssykler (3 hjul) c) 8 biler (4 hjul) d) 3 lastebiler med 6 hjul hver.","a":"a) 6 · 2 = 12. b) 4 · 3 = 12. c) 8 · 4 = 32. d) 3 · 6 = 18","ekstra":[]},{"id":"M5B-7.59","bok":"7.59 a-c","side":"94","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Skrive hopp på tallinje som gangestykker","q":"Hopp på en tallinje og skriv som gangestykker. a) 2, 3 og 4 hopp på 8 b) 5 hopp på 6, 6 hopp på 5, 7 hopp på 4 c) 6 hopp på 8, 5 hopp på 9, 9 hopp på 4.","a":"a) 2·8 = 16, 3·8 = 24, 4·8 = 32. b) 5·6 = 30, 6·5 = 30, 7·4 = 28. c) 6·8 = 48, 5·9 = 45, 9·4 = 36","ekstra":[]},{"id":"M5B-7.60","bok":"7.60 a-f","side":"94","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Visuell oppgave","niva":1,"figur":true,"ferdighet":"Telle øyne på terninger i rader og skrive som gangestykke","q":"Hvor mange øyne er det? Skriv som gangestykker. a) 5 terninger med 4 øyne b) 7 med 3 c) 6 med 5 d) 8 med 4 e) 7 med 6 f) 8 med 5.","a":"a) 5 · 4 = 20. b) 7 · 3 = 21. c) 6 · 5 = 30. d) 8 · 4 = 32. e) 7 · 6 = 42. f) 8 · 5 = 40","ekstra":[]},{"id":"M5B-7.61","bok":"7.61 a-c","side":"95","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Visuell oppgave","niva":1,"figur":true,"ferdighet":"Finne antall ruter og skrive gangestykke","q":"Hvor mange ruter er det? Rutenett: a) 3 · 5 b) 6 · 4 c) 7 · 8. Skriv som gangestykker.","a":"a) 3 · 5 = 15. b) 6 · 4 = 24. c) 7 · 8 = 56","ekstra":[]},{"id":"M5B-7.62","bok":"7.62 a-b","side":"95","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Dele opp et større rutenett og regne ut","q":"Hvor mange ruter er det? Del opp og regn ut. a) 4 · 18 b) 7 · 26","a":"a) 4·10 + 4·8 = 40 + 32 = 72. b) 7·20 + 7·6 = 140 + 42 = 182","ekstra":[]},{"id":"M5B-7.63","bok":"7.63 a-c","side":"95","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Gange tosifret med ensifret tall","q":"Regn ut. a) 14 · 6, 17 · 7, 36 · 5","a":"a) 14 · 6 = 84, 17 · 7 = 119, 36 · 5 = 180","ekstra":[]},{"id":"M5B-7.64","bok":"7.64 a-c","side":"96","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Finne manglende tall i gangestykker og skrive regnestykke","q":"Finn tallene som mangler. a) 3·□=18, □·4=20, 5·□=35, □·6=54 b) □·2=16, □·9=81, □·7=28, □·5=40 c) 6·□=36, 7·□=63, 4·□=32, 8·□=72","a":"a) 6, 5, 7, 9. b) 8, 9, 4, 8. c) 6, 9, 8, 9","ekstra":[]},{"id":"M5B-7.65","bok":"7.65 a-c","side":"96","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Regne ut delestykker","q":"Regn ut. a) 24 : 3, 30 : 6, 60 : 4 b) 35 : 5, 36 : 6, 54 : 6 c) 63 : 9, 72 : 9, 90 : 9","a":"a) 24 : 3 = 8, 30 : 6 = 5, 60 : 4 = 15 b) 35 : 5 = 7, 36 : 6 = 6, 54 : 6 = 9 c) 63 : 9 = 7, 72 : 9 = 8, 90 : 9 = 10","ekstra":[]},{"id":"M5B-7.66","bok":"7.66 a-c","side":"96","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Tekstoppgave","niva":3,"figur":false,"ferdighet":"Dele penger likt på flere barn","q":"Fordel pengene likt. a) 138 kr på tre barn b) 252 kr på fire barn c) 480 kr på fem barn.","a":"a) 138 : 3 = 46 kr. b) 252 : 4 = 63 kr. c) 480 : 5 = 96 kr","ekstra":[]},{"id":"M5B-S96-Gangebingo","bok":"Spill s. 96 «Gangebingo»","side":"96","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Spill / aktivitet","niva":1,"figur":true,"ferdighet":"Gange to terningkast og krysse av produktet på et bingobrett (1-36)","q":"Spill for to. Lag et bingobrett 4 × 4 med tall fra 1 til 36. Kast to terninger og gang tallene. Terningene viser 4 og 6. Hvilket tall krysser du av? Hvilke terningkast gir 12? Kan du få 7?","a":"4 · 6 = 24. 12 får du med 2·6, 3·4, 4·3 og 6·2. 7 kan ikke lages (7 er ikke produkt av to tall fra 1 til 6)","ekstra":[]},{"id":"M5B-7.67","bok":"7.67 a-h","side":"97","kap":7,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","type":"Mønster og logikk","niva":3,"figur":false,"ferdighet":"Fylle inn tallene 0-9 (hvert én gang) slik at regneuttrykk med parenteser stemmer","q":"Bruk tallene 0 til 9. Skriv ett tall i hver rute slik at regnestykket blir riktig. Hvert tall brukes bare én gang i hvert uttrykk. a) (□+□)+(□−□)=12 b) (□+□)·(□−□)=24 c) (□:□)·(□+□)=15 d) (□:□)·(□−□)=12","a":"Eksempler. a) (1+6)+(9−4) = 7 + 5 = 12. b) (3+5)·(7−4) = 8 · 3 = 24. c) (6:2)·(1+4) = 3 · 5 = 15. d) (8:4)·(9−3) = 2 · 6 = 12","ekstra":[]},{"id":"M5B-8.1","bok":"8.1 a-c","side":"99","kap":8,"tema":"Geometri og måling","emne":"Forskyvning, speiling og rotasjon","type":"Visuell oppgave","niva":1,"figur":true,"ferdighet":"Tegne av og fortsette figurmønstre på rutenett","q":"Tegn av og fortsett mønstrene. a) Rad: rød firkant, blå trekant, rød firkant, blå trekant, … b) Hver figur har én rute mer enn den før: 1, 2, 3 ruter, … c) Et kors av fem ruter flyttes to ruter til høyre hver gang.","a":"a) rød firkant, blå trekant, rød firkant, blå trekant (to figurer gjentas). b) 4, 5, 6 ruter. c) nytt kors flyttet 2 ruter til høyre hver gang (forskyvning)","ekstra":[]},{"id":"M5B-8.2","bok":"8.2","side":"99","kap":8,"tema":"Geometri og måling","emne":"Forskyvning, speiling og rotasjon","type":"Forklar og begrunn","niva":2,"figur":true,"ferdighet":"Kjenne igjen speiling, forskyvning og rotasjon i mønstre","q":"Mønster A: en trekant flyttes tre ruter til høyre hver gang. Mønster B: en figur speiles om en lodrett linje. Mønster C: en figur dreies 90° med klokka rundt et hjørne hver gang. Hvilken flytting er brukt i hvert mønster?","a":"A: forskyvning. B: speiling. C: rotasjon","ekstra":[]},{"id":"M5B-8.3","bok":"8.3","side":"99","kap":8,"tema":"Geometri og måling","emne":"Forskyvning, speiling og rotasjon","type":"Åpen utforsking","niva":2,"figur":true,"ferdighet":"Lage eget mønster ved å forskyve en figur på rutenett","q":"Tegn en figur på rutepapir. Forskyv den slik at du får et mønster. Bruk f.eks. en L-figur av tre ruter og flytt den fire ruter til høyre tre ganger.","a":"Åpen. Eksempel: L-figuren gjentas med 4 ruters mellomrom, til sammen 4 figurer på rad","ekstra":[]},{"id":"M5B-8.4","bok":"8.4 a-b","side":"100","kap":8,"tema":"Geometri og måling","emne":"Forskyvning, speiling og rotasjon","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Forskyve en figur et gitt antall ruter og beskrive forskyvningen","q":"a) En trekant har hjørnene (1,1), (3,1) og (1,3). Forskyv den 3 ruter til høyre og 4 ruter opp. Skriv de nye hjørnene. b) Lag et nytt mønster med samme figur og skriv hvor mange ruter og i hvilken retning du forskyver.","a":"a) (4,5), (6,5) og (4,7). b) Åpen. Eksempel: forskyv 3 ruter til høyre og 4 ruter opp gjentatte ganger","ekstra":[]},{"id":"M5B-8.5","bok":"8.5 a-b","side":"100","kap":8,"tema":"Geometri og måling","emne":"Forskyvning, speiling og rotasjon","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Speile en figur om en symmetrilinje på rutenett","q":"a) Speil punktene (2,1), (3,3) og (1,2) om den lodrette linjen x = 4. b) Speil punktene (2,3) og (4,4) om den vannrette linjen y = 5.","a":"a) (6,1), (5,3) og (7,2). b) (2,7) og (4,6)","ekstra":[]},{"id":"M5B-8.6","bok":"8.6","side":"101","kap":8,"tema":"Geometri og måling","emne":"Forskyvning, speiling og rotasjon","type":"Visuell oppgave","niva":3,"figur":true,"ferdighet":"Rotere en figur 90° flere ganger om et punkt","q":"En trekant har hjørnene (0,0), (3,0) og (0,2). Roter den 90° med klokka om (0,0) tre ganger. Skriv hjørnene etter hver rotasjon.","a":"Etter 90°: (0,0), (0,−3), (2,0). Etter 180°: (0,0), (−3,0), (0,−2). Etter 270°: (0,0), (0,3), (−2,0)","ekstra":[]},{"id":"M5B-8.7","bok":"8.7 a-c","side":"101","kap":8,"tema":"Geometri og måling","emne":"Forskyvning, speiling og rotasjon","type":"Åpen utforsking","niva":2,"figur":true,"ferdighet":"Lage mønstre med forskyvning, speiling og rotasjon","q":"Lag et mønster med a) forskyvning b) speiling c) rotasjon. Bruk en enkel figur på rutepapir.","a":"Åpen. Eksempler: a) trekant flyttet 2 ruter til høyre gjentatte ganger. b) figur speilet om lodrett linje, så speilet igjen. c) figur rotert 90° rundt samme hjørne fire ganger","ekstra":[]},{"id":"M5B-8.8","bok":"8.8","side":"101","kap":8,"tema":"Geometri og måling","emne":"Forskyvning, speiling og rotasjon","type":"Spill / aktivitet","niva":2,"figur":true,"ferdighet":"Lage et mønster ved å flytte en papp-mal rundt og tegne rundt","q":"Klipp en papp-mal på ca. 4 cm · 8 cm med en bit tatt ut. Teip biten på motsatt side, flytt malen rundt på et A4-ark og tegn rundt. Dekorer figurene.","a":"Åpen praktisk aktivitet. Mønsteret skal bestå av figurer som passer inn i hverandre uten mellomrom","ekstra":[]},{"id":"M5B-8.9","bok":"8.9 a-e","side":"102","kap":8,"tema":"Algebra og likninger","emne":"Figurrekker og figurtall","type":"Mønster og logikk","niva":1,"figur":true,"ferdighet":"Tegne de tre neste figurene i en rekke med fast system (gjentakelse, rotasjon, vekst)","q":"Tegn de tre neste figurene. a) ▲ ● ● ▲ ● ● ▲ ... b) ↑ → ↓ ← ↑ ... (pilen dreies 90° med klokka hver gang) c) ■ ■ □ ■ ■ □ ■ ...","a":"a) ● ● ▲. b) → ↓ ←. c) ■ □ ■","ekstra":[["Geometri og m?ling","Figurer og m?nster"]]},{"id":"M5B-8.10","bok":"8.10 a-d","side":"102","kap":8,"tema":"Algebra og likninger","emne":"Figurrekker og figurtall","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Velge neste figur i en rekke der flere egenskaper endrer seg (form, farge, plassering)","q":"Hvilken figur blir den neste? a) 1, 2, 3 og 4 trekanter på rad (neste?) b) En sirkel der ¼, så ½, så ¾ er farget (neste?) c) En prikk som flytter seg med klokka mellom hjørnene i en 2x2-rute: øverst venstre, øverst høyre, nederst høyre, nederst venstre (neste?)","a":"a) 5 trekanter. b) hel sirkel farget (4/4). c) prikken i øverst venstre hjørne","ekstra":[["Geometri og m?ling","Figurer og m?nster"]]},{"id":"M5B-8.11","bok":"8.11 a-d","side":"103","kap":8,"tema":"Algebra og likninger","emne":"Figurrekker og figurtall","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Finne neste figur når antall objekter vokser jevnt, og tegne to nye figurer","q":"a) Figur 1-3 har 2, 4 og 6 prikker. Hvor mange prikker har figur 4? b) I en rad med 5 ruter farges rute 1 i figur 1, rute 1-2 i figur 2 og rute 1-3 i figur 3. Hvor mange ruter er farget i figur 4? c) Tegn de to neste figurene i b).","a":"a) 8 prikker. b) 4 ruter. c) Figur 4: rute 1-4 farget, figur 5: alle 5 ruter farget","ekstra":[["Geometri og m?ling","Figurer og m?nster"]]},{"id":"M5B-8.12","bok":"8.12 a-b","side":"103","kap":8,"tema":"Algebra og likninger","emne":"Figurrekker og figurtall","type":"Mønster og logikk","niva":3,"figur":true,"ferdighet":"Finne manglende figur ved å lese rader og kolonner","q":"Hvilken figur mangler? a) Rad 1: ■ ● ▲, rad 2: ● ▲ ■, rad 3: ▲ ■ ?. b) Som a), men hver figur har også en farge. Rad 1: rød ●, blå ▲, grønn ■. Rad 2: blå ■, grønn ●, rød ▲. Rad 3: grønn ▲, rød ■, ?","a":"a) ●. b) blå ●","ekstra":[["Geometri og m?ling","Figurer og m?nster"]]},{"id":"M5B-8.13","bok":"8.13 a-d","side":"104","kap":8,"tema":"Algebra og likninger","emne":"Figurrekker og figurtall","type":"Tekstoppgave","niva":2,"figur":true,"ferdighet":"Tegne, lage tabell, finne mønster og bruke det til å finne antall for en stor figur","q":"Firkantbord settes etter hverandre. Ett bord har 4 stoler, to bord har 6, tre bord har 8. a) Hvor mange stoler er det rundt 4 bord? b) Fyll ut tabell for 5, 6 og 7 bord. c) Fyll ut for 8, 9 og 10 bord uten å tegne. d) Hvor mange stoler trengs til 20 bord?","a":"Regel: 2 · antall bord + 2. a) 10. b) 12, 14, 16. c) 18, 20, 22. d) 2·20+2 = 42 stoler","ekstra":[["Geometri og m?ling","Figurer og m?nster"]]},{"id":"M5B-8.14","bok":"8.14 a-d","side":"105","kap":8,"tema":"Algebra og likninger","emne":"Figurrekker og figurtall","type":"Tekstoppgave","niva":2,"figur":true,"ferdighet":"Finne mønster når antall øker med et fast tall hver gang, og bruke det på stor figur","q":"Bord stilles slik at 1 bord har 5 stoler, 2 bord har 8 og 3 bord har 11. a) Hvor mange stoler for 4 bord? b) Tabell for 5, 6 og 7 bord. c) Tabell for 8, 9 og 10 bord. d) Hvor mange stoler til 20 bord?","a":"Regel: 3 · antall bord + 2. a) 14. b) 17, 20, 23. c) 26, 29, 32. d) 62 stoler","ekstra":[["Geometri og m?ling","Figurer og m?nster"]]},{"id":"M5B-8.15","bok":"8.15 a-d","side":"105","kap":8,"tema":"Algebra og likninger","emne":"Figurrekker og figurtall","type":"Tekstoppgave","niva":2,"figur":true,"ferdighet":"Lage tabell for heller rundt blomsterbed og finne mønsteret","q":"Rundt 1 bed legges 6 heller, rundt 2 bed 11 heller og rundt 3 bed 16 heller. a) Hvor mange heller rundt 4 bed? b) Lag tabell for 1-5 bed. c) Hvor mange heller rundt 10 bed? d) Hvor mange rundt 20 bed?","a":"Regel: 5 · antall bed + 1. a) 21. b) 6, 11, 16, 21, 26. c) 51. d) 101 heller","ekstra":[["Geometri og m?ling","Figurer og m?nster"]]},{"id":"M5B-8.16","bok":"8.16 a-d","side":"106","kap":8,"tema":"Algebra og likninger","emne":"Figurrekker og figurtall","type":"Mønster og logikk","niva":2,"figur":true,"ferdighet":"Finne antall ruter i figurer med kvadratmønster og bruke mønsteret på store figurer","q":"Figur n består av n rader med n+1 ruter. Figur 1 har 2 ruter, figur 2 har 6 og figur 3 har 12. a) Figur 4? b) Figur 5 og 6? c) Figur 7, 8, 9 og 10? d) Figur 20, 50 og 100?","a":"Regel: n · (n+1). a) 20. b) 30 og 42. c) 56, 72, 90, 110. d) 420, 2550, 10100","ekstra":[["Geometri og m?ling","Figurer og m?nster"]]},{"id":"M5B-8.17","bok":"8.17 a-d","side":"107","kap":8,"tema":"Algebra og likninger","emne":"Figurrekker og figurtall","type":"Mønster og logikk","niva":3,"figur":true,"ferdighet":"Se at økningen vokser med 1 hver gang og finne tall i tabell opp til figur 12","q":"En trapp av klosser: figur 1 har 2 klosser, figur 2 har 5 og figur 3 har 9. a) Hvor mange klosser i figur 4? b) Hvor mange i figur 5, 6, 7 og 8? c) Hva er mønsteret? d) Fyll ut tabellen til figur 12.","a":"Økningen er 3, 4, 5, 6, ... a) 14. b) 20, 27, 35, 44. c) Tillegget øker med 1 for hver figur. d) Figur 9: 54, 10: 65, 11: 77, 12: 90","ekstra":[["Geometri og m?ling","Figurer og m?nster"]]},{"id":"M5B-8.18","bok":"8.18 a-b","side":"107","kap":8,"tema":"Algebra og likninger","emne":"Figurrekker og figurtall","type":"Tekstoppgave","niva":2,"figur":false,"ferdighet":"Summere en tallfølge der beløpet øker med fast tall hver dag","q":"Emil sparer. Første dag legger han 5 kr i sparegrisen, andre dag 10 kr, tredje dag 15 kr og så videre (5 kr mer hver dag). a) Hvor mye har han spart etter de ti første dagene? b) Etter de tjue første dagene?","a":"a) 5+10+...+50 = 5·55 = 275 kr. b) 5·(1+2+...+20) = 5·210 = 1050 kr","ekstra":[["Geometri og m?ling","Figurer og m?nster"]]},{"id":"M5B-8.19","bok":"8.19 a-c","side":"108","kap":8,"tema":"Algebra og likninger","emne":"Figurrekker og figurtall","type":"Mønster og logikk","niva":2,"figur":true,"ferdighet":"Tegne neste figurer, lage tabell, finne hvor mye antallet øker med","q":"Figur 1 er 1 rute, figur 2 er 4 ruter og figur 3 er 7 ruter. a) Hvordan ser figur 5 ut, og hvor mange ruter har den? b) Tegn eller regn ut figur 6, 7 og 8 og lag tabell. c) Hvor mye øker antallet med hver gang?","a":"a) Figur 4 = 10, figur 5 = 13. b) 16, 19, 22. c) 3 ruter","ekstra":[["Geometri og m?ling","Figurer og m?nster"]]},{"id":"M5B-8.20","bok":"8.20 a-c","side":"108","kap":8,"tema":"Algebra og likninger","emne":"Figurrekker og figurtall","type":"Mønster og logikk","niva":3,"figur":true,"ferdighet":"Tegne figurer, fylle tabell med økning og finne regel for at økningen vokser","q":"Figur 1 har 1 rute. Figur 2 får 3 ruter mer, figur 3 får 6 ruter mer enn figur 2, figur 4 får 9 mer enn figur 3, og slik fortsetter det. a) Hvor mange ruter har figur 4, 5 og 6? b) Fyll ut tabell til figur 8. c) Hvor mye øker antallet med for hver figur?","a":"Figur 1-8: 1, 4, 10, 19, 31, 46, 64, 85. a) 19, 31, 46. c) Økningen er 3, 6, 9, 12, 15, ... (øker med 3 hver gang)","ekstra":[["Geometri og m?ling","Figurer og m?nster"]]},{"id":"M5B-8.21","bok":"8.21 a-c","side":"108","kap":8,"tema":"Algebra og likninger","emne":"Figurrekker og figurtall","type":"Åpen utforsking","niva":3,"figur":true,"ferdighet":"Lage et eget figurtall, beskrive veksten og fylle tabell","q":"Lag et eget figurtall med fyrstikker. Tegn figur 1-3, lag tabell og finn hvor mye det øker med. (Eksempel: kvadrater på rad.)","a":"Åpent. Eksempel: 1 kvadrat = 4 fyrstikker, 2 = 7, 3 = 10. Økning 3 hver gang","ekstra":[["Geometri og m?ling","Figurer og m?nster"]]},{"id":"M5B-8.22","bok":"8.22 a-c","side":"109","kap":8,"tema":"Algebra og likninger","emne":"Figurrekker og figurtall","type":"Tekstoppgave","niva":3,"figur":true,"ferdighet":"Regne ut antall i kortbygg med flere etasjer og finne mønster til 10 etasjer","q":"Et tårn av esker har 3 etasjer og 15 esker. Etasje 1 har 3 esker, de to første etasjene til sammen har 8, og tre etasjer har 15. a) Hvor mange esker trengs for 2 etasjer? b) Fyll ut tabell for 1-5 etasjer. c) Hvor mange esker trengs til 10 etasjer?","a":"Regel: n · (n+2). a) 8. b) 3, 8, 15, 24, 35. c) 10·12 = 120 esker","ekstra":[["Geometri og m?ling","Figurer og m?nster"]]},{"id":"M5B-8.23","bok":"8.23 a-c","side":"109","kap":8,"tema":"Algebra og likninger","emne":"Figurrekker og figurtall","type":"Tekstoppgave","niva":2,"figur":true,"ferdighet":"Lage og bruke tabell der en fast del og en gjentatt del gir totalen","q":"En trikk har sjåfør og vogner med plass til 8 personer hver. Med to fulle vogner er det 17 personer. a) Hvor mange personer kan være med tre vogner? b) Fyll ut tabell for 0-5 vogner. c) Hvor mange personer med 20 vogner?","a":"Regel: 1 + 8 · vogner. a) 25. b) 1, 9, 17, 25, 33, 41. c) 1+160 = 161","ekstra":[["Geometri og m?ling","Figurer og m?nster"]]},{"id":"M5B-8.24","bok":"8.24 a-e","side":"110","kap":8,"tema":"Algebra og likninger","emne":"Tallfølger og mønster","type":"Tekstoppgave","niva":2,"figur":true,"ferdighet":"Fylle tabeller ved gjentatt addisjon og bruke multiplikasjon på stor mengde; deling med rest","q":"På basaren selges boller for 4 kr, juice for 6 kr og kaker for 12 kr. a) Fyll tabell for 1-9 boller. b) Fyll tabell for 5, 10, 15, 20 juice. c) Fyll tabell for 2, 4, 6, 8, 10, 12 kaker. d) Hva tjener de på 100 juice, 40 kaker og 50 boller? e) En mann kjøper kaker for 100 kr. Hvor mange kaker kan han få?","a":"a) 4, 8, 12, 16, 20, 24, 28, 32, 36. b) 30, 60, 90, 120. c) 24, 48, 72, 96, 120, 144. d) 600 kr, 480 kr, 200 kr. e) 100:12 = 8 rest 4, altså 8 kaker","ekstra":[]},{"id":"M5B-8.25","bok":"8.25 a-b","side":"111","kap":8,"tema":"Algebra og likninger","emne":"Tallfølger og mønster","type":"Mønster og logikk","niva":1,"figur":true,"ferdighet":"Fortsette korte tallfølger med fast differanse (tallinje kan brukes)","q":"Skriv de fire neste tallene. a) 3, 6, 9, 12, ... / 50, 45, 40, 35, ... b) 4, 7, 10, 13, ...","a":"a) 15, 18, 21, 24 / 30, 25, 20, 15. b) 16, 19, 22, 25","ekstra":[]},{"id":"M5B-8.26","bok":"8.26 a-b","side":"111","kap":8,"tema":"Algebra og likninger","emne":"Tallfølger og mønster","type":"Mønster og logikk","niva":2,"figur":false,"ferdighet":"Finne differansen og skrive de fire neste tallene (tall under 150)","q":"Skriv de fire neste tallene. a) 12, 18, 24, 30, ... / 25, 30, 35, 40, ... / 7, 15, 23, 31, ... b) 90, 85, 80, 75, ... / 100, 92, 84, 76, ... / 130, 127, 124, 121, ...","a":"a) 36, 42, 48, 54 / 45, 50, 55, 60 / 39, 47, 55, 63. b) 70, 65, 60, 55 / 68, 60, 52, 44 / 118, 115, 112, 109","ekstra":[]},{"id":"M5B-8.27","bok":"8.27 a-b","side":"111","kap":8,"tema":"Algebra og likninger","emne":"Tallfølger og mønster","type":"Mønster og logikk","niva":2,"figur":false,"ferdighet":"Skrive videre tallfølger med tall opp til 1000","q":"Skriv de fire neste tallene. a) 120, 220, 320, 420, ... / 840, 820, 800, 780, ... / 150, 265, 380, 495, ... b) 890, 880, 870, 860, ... / 450, 475, 500, 525, ... / 700, 685, 670, 655, ...","a":"a) 520, 620, 720, 820 / 760, 740, 720, 700 / 610, 725, 840, 955. b) 850, 840, 830, 820 / 550, 575, 600, 625 / 640, 625, 610, 595","ekstra":[]},{"id":"M5B-8.28","bok":"8.28 a-b","side":"111","kap":8,"tema":"Algebra og likninger","emne":"Tallfølger og mønster","type":"Mønster og logikk","niva":3,"figur":false,"ferdighet":"Skrive videre tallfølger med tall over 1000","q":"Skriv de fire neste tallene. a) 233, 334, 435, 536, ... / 410, 432, 454, 476, ... / 970, 860, 750, 640, ... b) 5120, 5020, 4920, 4820, ... / 1250, 1500, 1750, 2000, ... / 3000, 3600, 4200, 4800, ...","a":"a) 637, 738, 839, 940 / 498, 520, 542, 564 / 530, 420, 310, 200. b) 4720, 4620, 4520, 4420 / 2250, 2500, 2750, 3000 / 5400, 6000, 6600, 7200","ekstra":[]},{"id":"M5B-8.29","bok":"8.29 a-d","side":"111","kap":8,"tema":"Algebra og likninger","emne":"Tallfølger og mønster","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Finne manglende tall inne i en tallfølge","q":"Hvilke tall mangler? a) 4, ▢, 12, ▢, 20 b) ▢, 21, ▢, 33 c) 10, ▢, ▢, 25 d) ▢, ▢, 20, ▢, 32","a":"a) 8 og 16 (+4). b) 15 og 27 (+6). c) 15 og 20 (+5). d) 8, 14 og 26 (+6)","ekstra":[]},{"id":"M5B-8.30","bok":"8.30 a-c","side":"112","kap":8,"tema":"Algebra og likninger","emne":"Tallfølger og mønster","type":"Åpen utforsking","niva":3,"figur":true,"ferdighet":"Utforske hvilke steiner man lander på ved hopp med fast steg rundt en sirkel","q":"8 steiner står i sirkel og er nummerert 0-7. Mia starter på stein 0. a) Hun hopper på annenhver stein til hun lander på 0 igjen. Hvilke steiner lander hun på? b) Neste gang hopper hun på hver tredje stein til hun er tilbake på 0. Hvilke steiner? c) Undersøk hvilke steiner hun lander på ved hopp med 4, 5 og 6.","a":"a) 0, 2, 4, 6, 0. b) 0, 3, 6, 1, 4, 7, 2, 5, 0 (alle steinene). c) 4: 0, 4, 0. 5: 0, 5, 2, 7, 4, 1, 6, 3, 0 (alle). 6: 0, 6, 4, 2, 0","ekstra":[]},{"id":"M5B-8.31","bok":"8.31 ","side":"112","kap":8,"tema":"Algebra og likninger","emne":"Tallfølger og mønster","type":"Åpen utforsking","niva":3,"figur":false,"ferdighet":"Finne ulike regler som passer to gitte startverdier","q":"Finn minst tre ulike måter å fortsette tallfølgen 2, 5, ... på.","a":"Eksempler: +3 → 2, 5, 8, 11, ... ; +3, +5, +7 → 2, 5, 10, 17, ... ; gjentar → 2, 5, 2, 5, ...","ekstra":[]},{"id":"M5B-8.32","bok":"8.32 a-d","side":"112","kap":8,"tema":"Algebra og likninger","emne":"Tallfølger og mønster","type":"Ferdighetstrening","niva":3,"figur":false,"ferdighet":"Finne mønster (addisjon, dobling, halvering, kvadrattall) og fylle inn manglende tall","q":"Hvilke tall mangler? a) 3 – 6 – 12 – ▢ – 48 – ▢ – 192 b) 2 – ▢ – 10 – ▢ – 18 – ▢ – 26 c) 320 – 160 – ▢ – 40 – ▢ – 10 d) 1 – 3 – ▢ – 10 – ▢ – 21","a":"a) 24 og 96 (·2). b) 6, 14, 22 (+4). c) 80 og 20 (:2). d) 6 og 15 (trekanttall)","ekstra":[]},{"id":"M5B-8.33","bok":"8.33 a-b","side":"113","kap":8,"tema":"Algebra og likninger","emne":"Tallfølger og mønster","type":"Mønster og logikk","niva":3,"figur":true,"ferdighet":"Finne verdi på et snudd kort ved å se rad- og kolonnemønster","q":"Tre rader med kort: rad 1: 1, 3, 5; rad 2: 4, 6, 8; rad 3: 7, 9 og ett kort som er snudd. Hvilken verdi har det snudde kortet? Hvilket mønster bruker du?","a":"11. Hver rad øker med 2, og hver rad starter 3 høyere enn forrige","ekstra":[]},{"id":"M5B-8.34","bok":"8.34 a-b","side":"113","kap":8,"tema":"Algebra og likninger","emne":"Tallfølger og mønster","type":"Mønster og logikk","niva":3,"figur":true,"ferdighet":"Bruke addisjon/regning for å finne snudd kort i et 3x3-rutenett","q":"Kort i tre rader: rad 1: 2, 3, 5; rad 2: 4, 1, 5; rad 3: 6, 2 og et snudd kort. Hvilken verdi har det? Forklar regelen.","a":"8. Det tredje kortet i hver rad er summen av de to første (6 + 2 = 8)","ekstra":[]},{"id":"M5B-8.35","bok":"8.35 a-d","side":"114","kap":8,"tema":"Tall og regning","emne":"Tallfølger og mønster","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Addere nabotall og fylle toppen i pyramider; finne manglende tall bakover","q":"Legg sammen tallene ved siden av hverandre og skriv summen i ruta over. a) Nederste rad 3, 5, 2, 6. b) Nederste rad 4, 1, 7, 3, 5. c) Nederste rad 6, ▢, 9 og toppen er 25. d) Andre rad nedenfra 9, ▢, 11 og toppen er 40.","a":"a) 8, 7, 8 / 15, 15 / 30. b) 5, 8, 10, 8 / 13, 18, 18 / 31, 36 / 67. c) ▢ = 5 (6+5 = 11, 5+9 = 14, 11+14 = 25). d) ▢ = 10, tredje rad 19 og 21, topp 40","ekstra":[]},{"id":"M5B-8.36","bok":"8.36","side":"114","kap":8,"tema":"Tall og regning","emne":"Tallfølger og mønster","type":"Åpen utforsking","niva":2,"figur":true,"ferdighet":"Lage egen tallpyramide","q":"Lag en tallpyramide med 1, 2, 3, 4, 5 nederst. Hva blir toppen?","a":"4. rad: 3, 5, 7, 9. 3. rad: 8, 12, 16. 2. rad: 20, 28. Toppen: 48","ekstra":[]},{"id":"M5B-8.37","bok":"8.37 a-e","side":"115","kap":8,"tema":"Tall og regning","emne":"Tallfølger og mønster","type":"Ferdighetstrening","niva":3,"figur":true,"ferdighet":"Finne manglende tall slik at alle sumlinjer er like (3x3 og 4x4)","q":"Fyll inn slik at alle rader, kolonner og diagonaler får samme sum. a) Sum 24: 11 ▢ 9 / ▢ 8 ▢ / 7 ▢ 5. b) Sum 75: ▢ 5 30 / 15 25 ▢ / 20 ▢ 10. c) 4x4, sum 34: 16 3 2 ▢ / 5 10 ▢ 8 / ▢ 6 7 12 / 4 15 14 1.","a":"a) 4, 6, 10, 12 (rad 1: 11 4 9, rad 2: 6 8 10, rad 3: 7 12 5). b) 40, 35, 45. c) 13, 11, 9","ekstra":[]},{"id":"M5B-8.38","bok":"8.38 a-c","side":"116","kap":8,"tema":"Tall og regning","emne":"Tallmønster, tallpyramider og tallmaskiner","type":"Tolk data","niva":3,"figur":true,"ferdighet":"Finne verdien av figurer ut fra rad- og kolonnesummer","q":"Hver figur har en verdi. a) Rad 1: ★ ★ = 12. Rad 2: ★ ● = 9. Finn ★ og ●. b) Rad 1: ♥ ♥ ♥ = 15. Rad 2: ♥ ☘ ☘ = 17. Rad 3: ♥ ☘ ◆ = 20. Finn ♥, ☘ og ◆.","a":"a) ★ = 6, ● = 3. b) ♥ = 5, ☘ = 6, ◆ = 9","ekstra":[]},{"id":"M5B-8.39","bok":"8.39 a-b","side":"117","kap":8,"tema":"Tall og regning","emne":"Tallmønster, tallpyramider og tallmaskiner","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Regne både vannrett og loddrett i et tallkryss og fylle ut manglende tall","q":"Tegn et tallkryss. Første rute er 25. Vannrett: 25 + A = 60. Loddrett: 25 − B = 12. Finn A og B. b) Første rute er 8. Vannrett: 8 · A = 56. Loddrett: 8 + B = 15. Finn A og B.","a":"a) A = 35, B = 13. b) A = 7, B = 7","ekstra":[]},{"id":"M5B-8.40","bok":"8.40","side":"117","kap":8,"tema":"Tall og regning","emne":"Tallmønster, tallpyramider og tallmaskiner","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Tegne rutenett og fylle ut manglende produkter og faktorer","q":"Tegn rutenettet og fyll ut. Faktorer øverst: 3, 6, 8. Faktorer til venstre: 2, 5, 7. Kjente tall: 2·3 = 6, 5·6 = 30, 7·8 = 56. Fyll ut resten.","a":"Rad 2: 6, 12, 16. Rad 5: 15, 30, 40. Rad 7: 21, 42, 56","ekstra":[]},{"id":"M5B-8.41","bok":"8.41 a-c","side":"118","kap":8,"tema":"Tall og regning","emne":"Tallmønster, tallpyramider og tallmaskiner","type":"Ferdighetstrening","niva":2,"figur":true,"ferdighet":"Finne skjulte sifre i addisjon med to og tre sifre","q":"Hvilke sifre skjuler seg bak flekkene? a) 3▢ + ▢5 = 82 b) 3▢4 + ▢58 = 71▢ c) 6▢8 + 175 = 80▢","a":"a) 37 + 45 = 82 (7 og 4). b) 354 + 358 = 712 (5, 3, 2). c) 628 + 175 = 803 (2 og 3)","ekstra":[]},{"id":"M5B-8.42","bok":"8.42","side":"118","kap":8,"tema":"Tall og regning","emne":"Tallmønster, tallpyramider og tallmaskiner","type":"Ferdighetstrening","niva":3,"figur":true,"ferdighet":"Finne skjulte sifre i addisjon med fire sifre","q":"Hvilke sifre mangler? 2▢65 + 13▢2 = 3▢97","a":"2465 + 1332 = 3797. Sifrene er 4, 3 og 7","ekstra":[]},{"id":"M5B-8.43","bok":"8.43 a-b","side":"118","kap":8,"tema":"Tall og regning","emne":"Tallmønster, tallpyramider og tallmaskiner","type":"Ferdighetstrening","niva":3,"figur":true,"ferdighet":"Finne skjulte sifre i subtraksjon med veksling","q":"Hvilke sifre mangler? a) ▢62 − 3▢7 = 52▢ b) 9▢1 − 453 = ▢28","a":"a) 862 − 337 = 525 (8, 3, 5). b) 981 − 453 = 528 (8 og 5)","ekstra":[]},{"id":"M5B-8.44","bok":"8.44 a-c","side":"118","kap":8,"tema":"Tall og regning","emne":"Tallmønster, tallpyramider og tallmaskiner","type":"Ferdighetstrening","niva":3,"figur":true,"ferdighet":"Finne skjulte sifre i subtraksjon med tre til fire sifre","q":"Hvilke sifre mangler? 5▢82 − 24▢7 = ▢245","a":"5682 − 2437 = 3245. Sifrene er 6, 3 og 3","ekstra":[]},{"id":"M5B-8.45","bok":"8.45 a-c","side":"118","kap":8,"tema":"Tall og regning","emne":"Tallmønster, tallpyramider og tallmaskiner","type":"Ferdighetstrening","niva":3,"figur":true,"ferdighet":"Finne skjulte sifre i subtraksjon uten å regne alt ut","q":"Hvilke sifre mangler? a) 4▢7 − 175 = 32▢ b) 72▢ − 418 = 3▢7","a":"a) 497 − 175 = 322 (9 og 2). b) 725 − 418 = 307 (5 og 0)","ekstra":[]},{"id":"M5B-8.46","bok":"8.46","side":"118","kap":8,"tema":"Tall og regning","emne":"Tallmønster, tallpyramider og tallmaskiner","type":"Åpen utforsking","niva":3,"figur":false,"ferdighet":"Utforske mønster i differansen mellom et tall og tallet med byttet rekkefølge","q":"Bruk to ulike sifre til å lage et tosifret tall. Bytt om sifrene og finn differansen mellom de to tallene. Eksempel: 73 og 37. Gjør dette minst fem ganger. Ser du et mønster?","a":"73 − 37 = 36. Differansen er alltid 9 ganger differansen mellom sifrene: 7 og 3 gir 9·4 = 36, 62 − 26 = 36, 95 − 59 = 36, 81 − 18 = 63 (9·7). Differansen står alltid i 9-gangen","ekstra":[]},{"id":"M5B-8.47","bok":"8.47 a-d","side":"119","kap":8,"tema":"Algoritmer og programmering","emne":"Tallmønster, tallpyramider og tallmaskiner","type":"Mønster og logikk","niva":3,"figur":true,"ferdighet":"Bruke og analysere en regel i en maskin, og begrunne hvilke tall som kan komme ut","q":"En robot ganger tallet med 3 og trekker fra 2. a) Putt inn 2, 5, 8 og 12. Hvilke tall kommer ut? b) Kan roboten kaste ut 19? c) Kan den kaste ut 20 eller 21? d) Hvilke tall kan roboten ikke kaste ut? Forklar.","a":"a) 4, 13, 22, 34. b) Ja, 3·7−2 = 19, inn 7. c) Nei, 20 + 2 = 22 og 21 + 2 = 23 er ikke i 3-gangen. d) Svaret må være 2 mindre enn et tall i 3-gangen (1, 4, 7, 10, ...), så f.eks. 2, 3, 5, 6, 8, 9 kommer ikke ut","ekstra":[]},{"id":"M5B-8.48","bok":"8.48 a-d","side":"120","kap":8,"tema":"Algoritmer og programmering","emne":"Tallmønster, tallpyramider og tallmaskiner","type":"Mønster og logikk","niva":3,"figur":true,"ferdighet":"Bruke og analysere regel i en maskin og forklare hvilke tall som kan komme ut","q":"En robot legger først til 6 og halverer så svaret. a) Putt inn 4, 10, 16 og 30. b) Kan den kaste ut 9? c) Kan den kaste ut 20? d) Hva skjer hvis vi putter inn 7?","a":"a) 5, 8, 11, 18. b) Ja, inn 12. c) Ja, inn 34. d) (7+6) : 2 = 6,5, altså et desimaltall. Det blir hele tall bare når tallet inn er partall","ekstra":[]},{"id":"M5B-8.49","bok":"8.49","side":"121","kap":8,"tema":"Algoritmer og programmering","emne":"Tallmønster, tallpyramider og tallmaskiner","type":"Åpen utforsking","niva":2,"figur":true,"ferdighet":"Avsløre regel i en robot ut fra to inn-ut-par","q":"Hvis vi putter inn 4, kommer 22 ut. Putter vi inn 10, kommer 52 ut. Hva gjør roboten med tallene?","a":"Ganger med 5 og legger til 2 (4·5+2 = 22 og 10·5+2 = 52)","ekstra":[]},{"id":"M5B-8.50","bok":"8.50","side":"121","kap":8,"tema":"Algoritmer og programmering","emne":"Tallmønster, tallpyramider og tallmaskiner","type":"Åpen utforsking","niva":3,"figur":false,"ferdighet":"Lage egen robot og la en annen finne regelen","q":"Lag din egen robot som bruker to regneoperasjoner. La en annen finne ut hva roboten gjør.","a":"Åpent. Eksempel: legg til 4 og doble. Inn 3 gir 14, inn 6 gir 20","ekstra":[]},{"id":"M5B-PROVE-1-K8","bok":"Prøve 1 a-c","side":"123","kap":8,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 8)","type":"Mønster og logikk","niva":2,"figur":true,"ferdighet":"Lage mønster av en gitt figur ved forskyvning, speiling og rotasjon","q":"Tegn en L-formet figur av fire ruter i rutenett. a) Lag mønster ved forskyvning. b) Lag mønster ved speiling. c) Lag mønster ved rotasjon (90° med klokka hver gang).","a":"Åpent med kontroll: a) samme figur flyttes uten å dreies. b) hver ny figur er speilbildet over en felles linje. c) hver figur dreies 90° med klokka rundt samme hjørne","ekstra":[]},{"id":"M5B-PROVE-2-K8","bok":"Prøve 2 a-c","side":"123","kap":8,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 8)","type":"Mønster og logikk","niva":2,"figur":true,"ferdighet":"Tegne de tre neste figurene i rekker med fast system","q":"Tegn de tre neste figurene. a) ● ■ ▲ ● ■ ▲ ● b) en trekant som dreies 90° med klokka hver gang (start: spiss opp) c) 1 prikk, 3 prikker, 5 prikker, 7 prikker, ...","a":"a) ■ ▲ ●. b) spiss mot høyre, spiss ned, spiss mot venstre. c) 9, 11 og 13 prikker","ekstra":[]},{"id":"M5B-PROVE-3-K8","bok":"Prøve 3 a-b","side":"123","kap":8,"tema":"Geometri og måling","emne":"Prøve og øveside (kap. 8)","type":"Visuell oppgave","niva":2,"figur":true,"ferdighet":"Velge neste figur i rekke der to egenskaper endrer seg","q":"Hvilken figur blir den neste? a) Rød trekant, blå sirkel, rød trekant, blå sirkel, ... b) Et 2x2-rutenett der ruten med farge flytter seg med klokka: øverst venstre, øverst høyre, nederst høyre, ...","a":"a) rød trekant. b) nederst venstre","ekstra":[]},{"id":"M5B-PROVE-4-K8","bok":"Prøve 4 a-e","side":"124","kap":8,"tema":"Algebra og likninger","emne":"Prøve og øveside (kap. 8)","type":"Mønster og logikk","niva":3,"figur":true,"ferdighet":"Tegne neste figur, finne antall og lage tabell, forutsi stor figur","q":"Figurene vokser slik at figur 1 har 3 ruter, figur 2 har 5 ruter og figur 3 har 7 ruter. a) Tegn de to neste figurene. b) Hvor mange ruter i hver figur? c) Hvor mange i figur 4? d) Lag tabell til figur 6. e) Hvor mange ruter vil figur 15 ha?","a":"Regel: 2n + 1. a) tegning med 9 og 11 ruter. b) 3, 5, 7, 9, 11. c) 9. d) 3, 5, 7, 9, 11, 13. e) 31","ekstra":[]},{"id":"M5B-PROVE-5-K8","bok":"Prøve 5 a-c","side":"124","kap":8,"tema":"Algebra og likninger","emne":"Prøve og øveside (kap. 8)","type":"Mønster og logikk","niva":3,"figur":true,"ferdighet":"Tegne neste figurer, lage tabell, finne økning","q":"Figur 1 har 5 ruter, figur 2 har 9, figur 3 har 13. a) Tegn de to neste figurene. b) Hvor mange ruter har hver figur? Lag tabell og fyll ut til figur 6. c) Hvor mange ruter øker figurene med for hver figur?","a":"a) tegning med 17 og 21 ruter. b) 5, 9, 13, 17, 21, 25. c) 4 ruter","ekstra":[]},{"id":"M5B-PROVE-6-K8","bok":"Prøve 6 a-b","side":"124","kap":8,"tema":"Algebra og likninger","emne":"Prøve og øveside (kap. 8)","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Fortsette tallfølger med tre nye tall","q":"Hvilke tre tall er de neste? a) 30 – 33 – 36 – ... / 100 – 90 – 80 – ... / 402 – 502 – 602 – ... b) 12 – 24 – 36 – ... / 5 – 15 – 45 – ... / 800 – 400 – 200 – ...","a":"a) 39, 42, 45 / 70, 60, 50 / 702, 802, 902. b) 48, 60, 72 / 135, 405, 1215 / 100, 50, 25","ekstra":[]},{"id":"M5B-8.51","bok":"8.51 a-b","side":"125","kap":8,"tema":"Algebra og likninger","emne":"Prøve og øveside (kap. 8)","type":"Ferdighetstrening","niva":2,"figur":false,"ferdighet":"Finne de tre neste tallene i tallfølger","q":"Hvilke tre tall er de neste? a) 21 – 24 – 27 – ... / 85 – 80 – 75 – ... / 6 – 10 – 14 – ... b) 330 – 440 – 550 – ... / 520 – 510 – 500 – ... / 760 – 660 – 560 – ...","a":"a) 30, 33, 36 / 70, 65, 60 / 18, 22, 26. b) 660, 770, 880 / 490, 480, 470 / 460, 360, 260","ekstra":[]},{"id":"M5B-8.52","bok":"8.52 a-d","side":"125","kap":8,"tema":"Algebra og likninger","emne":"Prøve og øveside (kap. 8)","type":"Ferdighetstrening","niva":3,"figur":false,"ferdighet":"Finne manglende tall i tallfølger (pluss, gange 2, deling)","q":"Hvilke tall mangler? a) 15, 20, ▢, 30, ▢, 40 b) 9, ▢, 27, ▢, 45, 54, ▢ c) 5, 10, ▢, 40, 80, ▢, 320, ▢ d) 81000, 27000, ▢, 3000","a":"a) 25 og 35. b) 18, 36, 63 (+9). c) 20, 160, 640 (·2). d) 9000 (:3)","ekstra":[]},{"id":"M5B-8.53","bok":"8.53 a-b","side":"125","kap":8,"tema":"Algebra og likninger","emne":"Prøve og øveside (kap. 8)","type":"Ferdighetstrening","niva":3,"figur":true,"ferdighet":"Summere nabotall i en tallpyramide og finne manglende tall","q":"Legg sammen tallene ved siden av hverandre og skriv summen over. a) Nederste rad: 6, 8, 4, 10. b) Nederste rad: ▢, 5, 9, ▢ med rad to: 12, ▢, 17 og toppen 51.","a":"a) 14, 12, 14 / 26, 26 / 52. b) 7 + 5 = 12, 5 + 9 = 14, 9 + 8 = 17; rad 3: 26, 31; topp 57 (manglende: 7, 14 og 8)","ekstra":[]},{"id":"M5B-8.54","bok":"8.54 a-c","side":"126","kap":8,"tema":"Algebra og likninger","emne":"Prøve og øveside (kap. 8)","type":"Mønster og logikk","niva":3,"figur":true,"ferdighet":"Tegne neste figur i et delende mønster, lage tabell og finne mønster","q":"Start med ett grått kvadrat. I hver ny figur deles hvert grått kvadrat i 4 like kvadrater, og ett av dem blir hvitt. De hvite kvadratene deles også i 4 hvite. a) Tegn figur 3. b) Lag tabell med antall grå og hvite kvadrater for figur 1-4. c) Hvor mange grå og hvite er det i figur 4 og 5?","a":"Grå: 1, 3, 9, 27, 81 (ganges med 3). Hvite: 0, 1, 7, 37, 175. b) fig 1: 1 grå, 0 hvite; fig 2: 3 og 1; fig 3: 9 og 7; fig 4: 27 og 37. c) fig 4: 27 og 37; fig 5: 81 og 175","ekstra":[]},{"id":"M5B-8.55","bok":"8.55","side":"126","kap":8,"tema":"Algebra og likninger","emne":"Prøve og øveside (kap. 8)","type":"Åpen utforsking","niva":3,"figur":true,"ferdighet":"Finne regelen i Pascals trekant og lage større utgave","q":"I Pascals trekant er hvert tall summen av de to over. Radene begynner 1 / 1 1 / 1 2 1 / 1 3 3 1. Skriv rad 5 og 6, og finn summen av tallene i hver av de seks første radene.","a":"Rad 5: 1 4 6 4 1. Rad 6: 1 5 10 10 5 1. Radsummer: 1, 2, 4, 8, 16, 32 (dobles). Rad 8 har sum 128","ekstra":[]},{"id":"M5B-8.56","bok":"8.56 a-d","side":"127","kap":8,"tema":"Algebra og likninger","emne":"Prøve og øveside (kap. 8)","type":"Mønster og logikk","niva":3,"figur":true,"ferdighet":"Finne antall linjestykker mellom punkter, tabell og mønster","q":"Lag skal spille én kamp mot hvert av de andre lagene. 2 lag gir 1 kamp, 3 lag 3 kamper, 4 lag 6 kamper. a) Hvor mange kamper med 5 lag? b) Tabell for 2-7 lag. c) Se mønsteret og finn antall med 6 lag. Kontroller. d) Hvor mange kamper med 9 lag?","a":"b) 1, 3, 6, 10, 15, 21. a) 10. c) økning 2, 3, 4, 5, 6 → 15. d) 9·8:2 = 36 kamper","ekstra":[]},{"id":"M5B-8.57","bok":"8.57","side":"128","kap":8,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 8)","type":"Tekstoppgave","niva":3,"figur":true,"ferdighet":"Finne enkeltpriser når tre pris-par er kjent","q":"Kake + brus koster 25 kr, brus + is koster 20 kr og is + kake koster 31 kr. Hva koster hver?","a":"Sum av alle tre = (25+20+31):2 = 38. Is 38−25 = 13 kr, kake 38−20 = 18 kr, brus 38−31 = 7 kr","ekstra":[]},{"id":"M5B-8.58","bok":"8.58 a-b","side":"128","kap":8,"tema":"Tall og regning","emne":"Prøve og øveside (kap. 8)","type":"Mønster og logikk","niva":3,"figur":false,"ferdighet":"Finne tall ut fra sifferbeskrivelser og vurdere om det finnes flere løsninger","q":"a) Tre sifre. Tiersifferet er halvparten av enersifferet. Hundersifferet er summen av de to andre sifrene. Finnes det flere enn én løsning? b) Fire sifre. Enersifferet er 3. Tiersifferet er dobbelt så stort som enersifferet. Hundersifferet er halvparten av tiersifferet. Tverrsummen er 15.","a":"a) Ja, tre løsninger: 312, 624, 936. b) 3363 (tverrsum 3+3+6+3 = 15)","ekstra":[]},{"id":"RIK-01","bok":"Rik","side":"–","kap":0,"tema":"Tall og regning","emne":"Systematisk telling","type":"Rik oppgave","niva":2,"figur":false,"ferdighet":null,"q":"Pizzabutikken har fire toppinger: skinke, ost, sopp og ananas. Du skal velge to toppinger til pizzaen din. Hvor mange ulike pizzaer kan du lage? Vis hvordan du holder orden på valgene dine.","a":"To ulike toppinger, rekkefølge uten betydning: 6. Hvis samme topping kan velges to ganger: 10. Hvis rekkefølgen teller: 12. Strategier: liste, tabell, tegning eller fargebrikker.","videre":["Hva skjer hvis du kan velge samme topping to ganger?","Hva hvis det finnes fem toppinger? Finn en regel."],"rik":true,"ekstra":[["Statistikk og sannsynlighet","Kombinasjoner og sjanse"]]},{"id":"RIK-02","bok":"Rik","side":"–","kap":0,"tema":"Tall og regning","emne":"Systematisk telling","type":"Rik oppgave","niva":2,"figur":false,"ferdighet":null,"q":"Mia har 3 gensere og 4 bukser. Hvor mange ulike antrekk kan hun lage? Vis det på to ulike måter.","a":"3 · 4 = 12. Strategier: tabell, tegning, tre-diagram, gjentatt addisjon (4+4+4).","videre":["Hva hvis hun også har 2 par sko?","Hvor mange ulike antrekk er det hvis én genser ikke passer til to av buksene?"],"rik":true,"ekstra":[]},{"id":"RIK-03","bok":"Rik","side":"–","kap":0,"tema":"Tall og regning","emne":"Systematisk telling","type":"Rik oppgave","niva":2,"figur":false,"ferdighet":null,"q":"Seks elever hilser på hverandre med håndtrykk. Alle hilser på alle akkurat én gang. Hvor mange håndtrykk blir det?","a":"15 (5+4+3+2+1). Strategier: tegne punkter og streker, tabell, spille det ut i gruppa, summere 5+4+3+2+1.","videre":["Hvor mange håndtrykk blir det med 10 elever?","Finner du en regel for n elever?"],"rik":true,"ekstra":[["Algebra og likninger","Tallfølger og mønster"]]},{"id":"RIK-04","bok":"Rik","side":"–","kap":0,"tema":"Tall og regning","emne":"Systematisk telling","type":"Rik oppgave","niva":3,"figur":false,"ferdighet":null,"q":"Du har 5-kroner, 10-kroner og 20-kroner. På hvor mange måter kan du betale akkurat 50 kr? Finn en måte å ordne løsningene på slik at du ikke glemmer noen.","a":"Bare 5- og 10-kroner: 6 måter. Med 20-kroner i tillegg: 12 måter. Strategi: systematisk tabell, start med flest 20-kroner og jobb nedover.","videre":["Hva hvis du bare har 5-kroner og 20-kroner?","Lag en egen betalingsoppgave og la sidemannen løse den."],"rik":true,"ekstra":[]},{"id":"RIK-05","bok":"Rik","side":"–","kap":0,"tema":"Tall og regning","emne":"Mønster og generalisering","type":"Rik oppgave","niva":2,"figur":false,"ferdighet":null,"q":"Hvor mange ganger står tallet 12 i gangetabellen fra 1 · 1 til 10 · 10? Hvilke tall står oftest? Forklar hvorfor.","a":"12 står 4 ganger (2·6, 6·2, 3·4, 4·3). Tall med mange faktorpar går igjen oftest. Strategier: fargelegge en gangetabell, liste faktorer.","videre":["Hvilke tall står bare én eller to ganger?","Hvilket tall under 50 står flest ganger?"],"rik":true,"ekstra":[]},{"id":"RIK-06","bok":"Rik","side":"–","kap":0,"tema":"Tall og regning","emne":"Mønster og generalisering","type":"Rik oppgave","niva":2,"figur":false,"ferdighet":null,"q":"24 elever skal deles i like store grupper. Hvilke gruppestørrelser går opp? Sammenlikn med 30 og 36 elever. Hvilket antall gir flest valg?","a":"24: 1, 2, 3, 4, 6, 8, 12, 24 (8 valg). 30: 1, 2, 3, 5, 6, 10, 15, 30 (8 valg). 36: 1, 2, 3, 4, 6, 9, 12, 18, 36 (9 valg). Strategier: gangefakta, divisjon, rektangler.","videre":["Hvilket tall under 50 har flest muligheter?","Hvorfor har noen tall bare to muligheter?"],"rik":true,"ekstra":[]},{"id":"RIK-07","bok":"Rik","side":"–","kap":0,"tema":"Tall og regning","emne":"Åpne problemer","type":"Rik oppgave","niva":1,"figur":false,"ferdighet":null,"q":"Svaret er 24. Hva kan spørsmålet være? Skriv så mange ulike regnestykker du kan, og bruk gjerne både pluss, minus, gange og dele.","a":"Åpen oppgave: for eksempel 20+4, 6·4, 48:2, 30−6, 3·8, (10+2)·2. Elevene viser ulike strategier og regneartene.","videre":["Lag et regnestykke med minst tre ledd og svar 24.","Bytt svar med en ved siden av deg og finn flere regnestykker til hverandres svar."],"rik":true,"ekstra":[]},{"id":"RIK-08","bok":"Rik","side":"–","kap":0,"tema":"Algebra og likninger","emne":"Balanse og ukjente","type":"Rik oppgave","niva":3,"figur":false,"ferdighet":null,"q":"Tre like pakker A og to like pakker B veier til sammen 1 100 g. En pakke A og to pakker B veier til sammen 700 g. Hvor mye veier én pakke A og én pakke B? Du kan ikke åpne pakkene.","a":"Sammenlikn: to A-pakker veier 400 g, så A = 200 g. Da er 2B = 500 g og B = 250 g. Strategier: sammenlikne, tegning, prøving og feiling, likning.","videre":["Lag en lignende oppgave med andre vekter.","Hva må være sant for at oppgaven kan løses?"],"rik":true,"ekstra":[["Tall og regning","Regning med ukjente tall"]]},{"id":"RIK-09","bok":"Rik","side":"–","kap":0,"tema":"Algebra og likninger","emne":"Balanse og ukjente","type":"Rik oppgave","niva":2,"figur":false,"ferdighet":null,"q":"Ola er 3 år eldre enn Eli. Sammen er de 25 år. Hvor gamle er de? Finn løsningen på to ulike måter.","a":"Ola 14, Eli 11. Strategier: prøving og feiling, tegne to stolper, 25 − 3 = 22 og 22 : 2 = 11, likning.","videre":["Hva hvis forskjellen er 5 år og summen 31?","Når kan oppgaven ikke løses med hele tall?"],"rik":true,"ekstra":[["Tall og regning","Regning med ukjente tall"]]},{"id":"RIK-10","bok":"Rik","side":"–","kap":0,"tema":"Algebra og likninger","emne":"Balanse og ukjente","type":"Rik oppgave","niva":2,"figur":false,"ferdighet":null,"q":"På en gård er det høner og kuer. Til sammen er det 10 hoder og 28 bein. Hvor mange høner og kuer er det? Forklar hvordan du tenkte.","a":"6 høner og 4 kuer (12 + 16 = 28). Strategier: tabell med prøving, tegne hoder og bein, gi alle dyr 2 bein og fordele resten.","videre":["Hva hvis det er 12 hoder og 38 bein?","Finn et antall bein som ikke går an."],"rik":true,"ekstra":[["Tall og regning","Regning med ukjente tall"]]},{"id":"RIK-11","bok":"Rik","side":"–","kap":0,"tema":"Algebra og likninger","emne":"Mønster og generalisering","type":"Rik oppgave","niva":3,"figur":false,"ferdighet":null,"q":"Summen av tre tall på rad er 48. Hvilke tre tall er det? Hvilke summer er mulige for tre tall på rad?","a":"15, 16, 17 (midtre tall = 48 : 3). Mulige summer: alle tall i 3-gangen. Strategier: prøving, tegning, jevne ut.","videre":["Gjelder det samme for fire tall på rad?","Hvorfor blir summen alltid delelig med 3?"],"rik":true,"ekstra":[["Tall og regning","Tallmønster"]]},{"id":"RIK-12","bok":"Rik","side":"–","kap":0,"tema":"Algebra og likninger","emne":"Mønster og generalisering","type":"Rik oppgave","niva":2,"figur":false,"ferdighet":null,"q":"Du bygger kvadrater av fyrstikker som ligger i en rad: 1 kvadrat trenger 4 fyrstikker, 2 kvadrater trenger 7, 3 kvadrater trenger 10. Hvor mange fyrstikker trenger du til 10 kvadrater? Finn en regel.","a":"31 fyrstikker. Regel: 3 · antall kvadrater + 1. Strategier: tegne, tabell, fortsette mønsteret, forklare strukturen (1 + 3 for hver).","videre":["Hvor mange kvadrater får du av 100 fyrstikker?","Lag en egen figurrekke og skriv regelen."],"rik":true,"ekstra":[["Geometri og måling","Figurer og mønster"]]},{"id":"RIK-13","bok":"Rik","side":"–","kap":0,"tema":"Algebra og likninger","emne":"Mønster og generalisering","type":"Rik oppgave","niva":2,"figur":false,"ferdighet":null,"q":"Tallpyramide med tre ruter nederst. Tallet i hver rute over er summen av de to rutene under. Du skal plassere tallene 1, 2 og 3 nederst, hver én gang. Hvor stort kan tallet øverst bli? Og hvor lite?","a":"Størst 9 (3 i midten: 1+3 + 3+2 = 9). Minst 7 (1 i midten). Det midterste tallet telles to ganger. Strategier: prøve alle 6 plasseringene systematisk.","videre":["Hva om tallene er 2, 3 og 4?","Forklar hvorfor midtruten betyr mest."],"rik":true,"ekstra":[["Tall og regning","Tallmønster"]]},{"id":"RIK-14","bok":"Rik","side":"–","kap":0,"tema":"Geometri og måling","emne":"Form og måling","type":"Rik oppgave","niva":2,"figur":false,"ferdighet":null,"q":"Du har et rektangel med omkrets 24 cm og hele centimeter på sidene. Finn alle rektanglene som går. Hvilket har størst areal?","a":"1×11 (11), 2×10 (20), 3×9 (27), 4×8 (32), 5×7 (35), 6×6 (36). Kvadratet har størst areal. Strategier: tabell, rutenett, tegning.","videre":["Hva skjer med arealet når rektangelet blir mer og mer likt et kvadrat?","Gjør det samme med omkrets 30 cm."],"rik":true,"ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"RIK-15","bok":"Rik","side":"–","kap":0,"tema":"Geometri og måling","emne":"Form og måling","type":"Rik oppgave","niva":2,"figur":false,"ferdighet":null,"q":"Et rektangel har areal 36 cm² og hele centimeter på sidene. Finn alle mulige rektangler og regn ut omkretsen til hver av dem. Hva legger du merke til?","a":"1×36 (74 cm), 2×18 (40), 3×12 (30), 4×9 (26), 6×6 (24). Samme areal gir ulik omkrets; kvadratet har minst omkrets.","videre":["Kan to rektangler ha samme areal men ulik omkrets? Samme omkrets men ulikt areal?"],"rik":true,"ekstra":[["Tall og regning","Multiplikasjon og areal"]]},{"id":"RIK-16","bok":"Rik","side":"–","kap":0,"tema":"Geometri og måling","emne":"Form og måling","type":"Rik oppgave","niva":3,"figur":false,"ferdighet":null,"q":"Bonden har 20 m gjerde og skal lage en innhegning mot en vegg, slik at han bare trenger gjerde på tre sider. Hvilke mål gir størst areal? Lag en tabell.","a":"Bredde (to sider) w og lengde l = 20 − 2w: 5 m × 10 m gir størst areal 50 m². Strategier: tabell, tegning på rutenett, prøving.","videre":["Hva hvis han har 30 m gjerde?","Hva hvis innhegningen ligger i et hjørne mellom to vegger?"],"rik":true,"ekstra":[["Algebra og likninger","Prøving og feiling"]]},{"id":"RIK-17","bok":"Rik","side":"–","kap":0,"tema":"Geometri og måling","emne":"Form og måling","type":"Rik oppgave","niva":3,"figur":false,"ferdighet":null,"q":"Hvor mange kvadrater (av alle størrelser) finner du i et rutenett med 4 × 4 ruter? Hvordan sørger du for at du ikke teller noen to ganger?","a":"30 kvadrater: 16 av størrelse 1×1, 9 av 2×2, 4 av 3×3 og 1 av 4×4. Strategier: systematisk telling etter størrelse, start med mindre rutenett (2×2: 5, 3×3: 14).","videre":["Hvor mange kvadrater er det i et 5 × 5-rutenett?","Finner du et mønster?"],"rik":true,"ekstra":[["Tall og regning","Systematisk telling"]]},{"id":"RIK-18","bok":"Rik","side":"–","kap":0,"tema":"Geometri og måling","emne":"Form og måling","type":"Rik oppgave","niva":3,"figur":false,"ferdighet":null,"q":"Lag et kart over klasserommet ditt på et A4-ark. Hvilken målestokk passer? Hvordan velger og begrunner du den?","a":"Åpen oppgave: mål rommet (for eksempel 8 m × 6 m), prøv målestokk 1 : 50 (16 cm × 12 cm) og 1 : 40, og velg slik at kartet fyller arket. Strategier: måle, regne om enheter, skissere.","videre":["Hvilken målestokk trenger du for å tegne hele skolegården?","Sammenlikn kartet ditt med et annet."],"rik":true,"ekstra":[["Tall og regning","Regning med mål"]]},{"id":"RIK-19","bok":"Rik","side":"–","kap":0,"tema":"Brøk, desimaltall og prosent","emne":"Brøk og deler","type":"Rik oppgave","niva":2,"figur":false,"ferdighet":null,"q":"Del et kvadrat i fire like store deler på så mange ulike måter du kan. Hvordan vet du at delene er like store?","a":"Eksempler: fire like stolper, fire like kvadrater, trekanter fra diagonalene, L-former. Delene er like store når de har samme areal (kan dekke hverandre eller telle ruter).","videre":["Gjør det samme med 8 like deler.","Er delene med ulik form like store? Hvordan kan du sjekke?"],"rik":true,"ekstra":[["Geometri og måling","Figurer og mønster"]]},{"id":"RIK-20","bok":"Rik","side":"–","kap":0,"tema":"Brøk, desimaltall og prosent","emne":"Brøk og deler","type":"Rik oppgave","niva":2,"figur":false,"ferdighet":null,"q":"Hva er størst: 3/4 eller 5/8? Finn minst tre ulike måter å begrunne svaret på.","a":"3/4 er størst. Måter: tegning av like store figurer, felles nevner (6/8 mot 5/8), tallinje, avstand til 1 (1/4 = 2/8 mangler mot 3/8).","videre":["Finn to andre brøker der det er vanskelig å se hvem som er størst.","Lag en regel for å sammenlikne brøker."],"rik":true,"ekstra":[]},{"id":"RIK-21","bok":"Rik","side":"–","kap":0,"tema":"Brøk, desimaltall og prosent","emne":"Brøk og deler","type":"Rik oppgave","niva":3,"figur":false,"ferdighet":null,"q":"Finn en brøk som ligger mellom 1/4 og 1/2. Finn flere. Går det an å fortsette for alltid? Vis på en tallinje.","a":"Eksempler: 3/8, 1/3, 5/12, 2/5. Ja, det finnes uendelig mange brøker mellom to brøker (gjør nevnerne større). Strategier: tallinje, felles nevner (2/8 og 4/8 → 3/8), tegning.","videre":["Finn en brøk mellom 3/8 og 1/2.","Skriv brøkene dine som desimaltall der det går."],"rik":true,"ekstra":[["Tall og regning","Tall og tallinje"]]},{"id":"RIK-22","bok":"Rik","side":"–","kap":0,"tema":"Statistikk og sannsynlighet","emne":"Kombinasjoner og sjanse","type":"Rik oppgave","niva":2,"figur":false,"ferdighet":null,"q":"Du kaster to terninger og legger sammen øynene. Hvilken sum er lettest å få, og hvilken er vanskeligst? Lag en tabell som viser alle mulighetene.","a":"7 er lettest (6 av 36 kombinasjoner), 2 og 12 er vanskeligst (1 av 36 hver). Strategier: tabell 6 × 6, systematisk liste, prøving med faktiske terninger.","videre":["Lag et spill der to spillere velger hver sine summer. Er spillet rettferdig?","Hva hvis terningene har 4 sider?"],"rik":true,"ekstra":[["Tall og regning","Systematisk telling"]]}],"eksempler":[{"id":"M5B-EKS-S7","side":"6-7","tema":"Geometri og måling","emne":"Vi måler lengder","q":"Bruk en målenhet bak tallene slik at de beskriver riktig lengde. a) Høyden på et tre er 12. b) Lengden av en blyant er 19.","a":"a) 12 m. b) 19 cm"},{"id":"M5B-EKS-S10","side":"10","tema":"Geometri og måling","emne":"Omkrets","q":"Et rektangel på prikkark er 3 prikkavstander langt og 2 bredt. Hva er omkretsen?","a":"3 + 2 + 3 + 2 = 10"},{"id":"M5B-EKS-S14","side":"14","tema":"Geometri og måling","emne":"Areal","q":"En hånd lagt på rutepapir dekker 12 hele ruter og 6 halve ruter. Omtrent hvor mange ruter dekker den?","a":"12 + 6 : 2 = 12 + 3 = 15 ruter"},{"id":"M5B-EKS-S16","side":"16","tema":"Geometri og måling","emne":"Areal","q":"Hva er arealet? a) Figur med 4 hele ruter og 2 halve ruter. b) En rettvinklet trekant som er halvparten av et rektangel på 2 · 3.","a":"a) 4 + 1 = 5. b) 6 : 2 = 3"},{"id":"M5B-EKS-S18","side":"18","tema":"Geometri og måling","emne":"Areal","q":"Hvor mange cm² er et rektangel med 3 rader og 6 ruter i hver rad?","a":"6 · 3 = 18 cm²"},{"id":"M5B-EKS-S19","side":"19","tema":"Geometri og måling","emne":"Areal","q":"Tegn et rektangel med areal 20 cm² og én side på 5 cm.","a":"Den andre siden er 4 cm fordi 5 · 4 = 20"},{"id":"M5B-EKS-S24","side":"24","tema":"Geometri og måling","emne":"Målestokk","q":"Kart med målestokk 1 : 1000. Avstanden mellom to boder er 6 cm på kartet. Hvor langt er det i virkeligheten?","a":"6 · 10 = 60 m"},{"id":"M5B-EKS-S35","side":"35","tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","q":"En pose har 7 brikker: 3 røde, 2 blå og 2 gule. a) Hvor stor del er røde? b) Hvor stor del er gule?","a":"a) 3/7. b) 2/7"},{"id":"M5B-EKS-S38","side":"38","tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","q":"En stripe er delt i 8 like ruter. 3 ruter er røde og resten blå. Hvor stor del er rød, og hvor stor del er blå?","a":"Rød 3/8. Blå 5/8 (3/8 + 5/8 = 1)"},{"id":"M5B-EKS-S40","side":"40","tema":"Brøk, desimaltall og prosent","emne":"Brøk som del av en helhet","q":"Et rektangel på 3 ruter er 1/3 av en figur. Hvor mange ruter har hele figuren? Tegn den.","a":"3 · 3 = 9 ruter (tre like rektangler)"},{"id":"M5B-EKS-S44A","side":"44","tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","q":"Skriv en brøk der teller og nevner er dobbelt så store som i 3/4.","a":"3/4 = 6/8"},{"id":"M5B-EKS-S44B","side":"44","tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","q":"Skriv en brøk der teller og nevner er halvparten så store som i 6/8.","a":"6/8 = 3/4"},{"id":"M5B-EKS-S46","side":"46","tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","q":"Hvilken brøk mangler? 3/8 + ? = 1","a":"5/8 (3/8 + 5/8 = 8/8 = 1)"},{"id":"M5B-EKS-S51","side":"51","tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","q":"Hvor mye er 2/5 + 1/5? Tegn en stripe delt i 5 deler.","a":"2/5 + 1/5 = 3/5"},{"id":"M5B-EKS-S52","side":"52","tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","q":"Hvor mye er 1/6 + 2/6 + 2/6?","a":"5/6"},{"id":"M5B-EKS-S53","side":"53","tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","q":"Hvor mye er 5/6 - 2/6?","a":"3/6"},{"id":"M5B-EKS-S54","side":"54","tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","q":"To striper er delt i 8 deler. Den ene har 6 deler farget og den andre 2. Hva er forskjellen?","a":"6/8 - 2/8 = 4/8"},{"id":"M5B-EKS-S55","side":"55","tema":"Brøk, desimaltall og prosent","emne":"Addisjon og subtraksjon av brøker","q":"Hvor mye er 7/9 - 4/9?","a":"3/9"},{"id":"M5B-EKS-S56","side":"56","tema":"Brøk, desimaltall og prosent","emne":"Blandede tall","q":"Hvor mye er 5/6 + 4/6?","a":"9/6 = 1 3/6"},{"id":"M5B-EKS-S57","side":"57","tema":"Brøk, desimaltall og prosent","emne":"Blandede tall","q":"Hvor mye er 3/5 + 4/5?","a":"7/5 = 1 2/5"},{"id":"M5B-EKS-S58","side":"58","tema":"Brøk, desimaltall og prosent","emne":"Blandede tall","q":"Hvor mye er 1 1/4 - 3/4?","a":"5/4 - 3/4 = 2/4"},{"id":"M5B-EKS-S68A","side":"68","tema":"Tall og regning","emne":"Multiplikasjon","q":"Det er 3 katter i hver av 7 kurver. Hvor mange katter er det? Skriv som gangestykke.","a":"3 · 7 = 21 katter"},{"id":"M5B-EKS-S68B","side":"68","tema":"Tall og regning","emne":"Multiplikasjon","q":"En gresshoppe hopper 4 cm per hopp. Hvor langt har den hoppet etter 5 hopp?","a":"5 · 4 = 20 cm"},{"id":"M5B-EKS-S69","side":"69","tema":"Tall og regning","emne":"Multiplikasjon","q":"Et tårn av 4 klosser er 24 cm høyt. Hvor høy er hver kloss?","a":"4 · 6 = 24, så hver kloss er 6 cm"},{"id":"M5B-EKS-S72","side":"72-73","tema":"Tall og regning","emne":"Multiplikasjon","q":"Mia kjøper fire kanelbolser til 6 kr stykket. Hva må hun betale?","a":"4 · 6 = 24. Hun betaler 24 kroner"},{"id":"M5B-EKS-S76","side":"76-77","tema":"Tall og regning","emne":"Multiplikasjon på rutenett og tosifrede tall","q":"Hvor mange ruter er det i et rutenett som er 6 ruter langt og 4 ruter høyt? Skriv som gangestykke.","a":"6 · 4 = 24 ruter"},{"id":"M5B-EKS-S78","side":"78-79","tema":"Tall og regning","emne":"Multiplikasjon på rutenett og tosifrede tall","q":"Hvor mange ruter er det i et rutenett som er 14 · 6? Del opp og regn ut.","a":"10 · 6 = 60 og 4 · 6 = 24. 60 + 24 = 84 ruter"},{"id":"M5B-EKS-S78-b","side":"78-79","tema":"Tall og regning","emne":"Multiplikasjon på rutenett og tosifrede tall","q":"Hvor mye er 13 · 8?","a":"10 · 8 = 80 og 3 · 8 = 24. 80 + 24 = 104"},{"id":"M5B-EKS-S79","side":"78-79","tema":"Tall og regning","emne":"Multiplikasjon på rutenett og tosifrede tall","q":"Regn ut 27 · 4 ved å dele opp.","a":"20 · 4 = 80 og 7 · 4 = 28. 80 + 28 = 108"},{"id":"M5B-EKS-S80","side":"80-81","tema":"Tall og regning","emne":"Multiplikasjon på rutenett og tosifrede tall","q":"Regn ut 12 · 15 ved å dele opp.","a":"10·10 = 100, 10·5 = 50, 2·10 = 20, 2·5 = 10. 100 + 50 + 20 + 10 = 180"},{"id":"M5B-EKS-S81","side":"80-81","tema":"Tall og regning","emne":"Multiplikasjon på rutenett og tosifrede tall","q":"Regn ut 24 · 11.","a":"240 + 24 = 264"},{"id":"M5B-EKS-S83","side":"82-83","tema":"Tall og regning","emne":"Divisjon og delestykker","q":"Hvor mye er 20 : 4?","a":"4 · 5 = 20, så 20 : 4 = 5"},{"id":"M5B-EKS-S84","side":"84-85","tema":"Tall og regning","emne":"Divisjon og delestykker","q":"Hvor mange tårn på 6 klosser kan lages av 48 klosser?","a":"48 : 6 = 8 tårn"},{"id":"M5B-EKS-S87","side":"86-87","tema":"Tall og regning","emne":"Divisjon og delestykker","q":"Jonas selger kaker til 6 kr per stykke og har solgt 7 kaker. Hvor mye har han tjent?","a":"7 · 6 = 42. Han har tjent 42 kroner"},{"id":"M5B-EKS-S88","side":"88-89","tema":"Tall og regning","emne":"Tekstoppgaver og divisjon med større tall","q":"Fire barn deler 156 kr likt. Hvor mye får hvert barn?","a":"Første runde 4 · 30 = 120, rest 36; så 4 · 9 = 36. 30 + 9 = 39. Hvert barn får 39 kr"},{"id":"M5B-EKS-S97","side":"96-97","tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","q":"Hvilke tall kan stå i rutene i (□+□)+(□−□)=10? Bruk hvert tall bare én gang.","a":"Eksempel: (4+2)+(9−5) = 6 + 4 = 10. Tallene 4, 2, 9 og 5 er forskjellige"},{"id":"M5B-EKS-S100","side":"100-101","tema":"Geometri og måling","emne":"Forskyvning, speiling og rotasjon","q":"Et kvadrat på 2 · 2 ruter har nederste venstre hjørne i (2, 2). Forskyv det 3 ruter til høyre og 2 ruter opp. Hvor havner det nederste venstre hjørnet?","a":"Nytt hjørne: (2 + 3, 2 + 2) = (5, 4)"},{"id":"M5B-EKS-S105","side":"104-105","tema":"Algebra og likninger","emne":"Figurrekker og figurtall","q":"Rundt én bolle står 5 lys. Hver ny bolle gir 3 lys til. Hvor mange lys er det rundt 3 boller?","a":"5 + 3 + 3 = 11 lys"},{"id":"M5B-EKS-S115","side":"114-115","tema":"Tall og regning","emne":"Tallfølger og mønster","q":"Vis at kvadratet 9 2 7 / 4 6 8 / 5 10 3 er magisk. Hva er summen?","a":"Alle rader (9+2+7, 4+6+8, 5+10+3), kolonner (9+4+5, 2+6+10, 7+8+3) og diagonaler (9+6+3, 7+6+5) = 18. Summen er 18"},{"id":"M5B-EKS-S119","side":"119","tema":"Algoritmer og programmering","emne":"Tallmønster, tallpyramider og tallmaskiner","q":"En robot legger først til 3 på tallet og dobler svaret. Hva kommer ut når vi putter inn 8?","a":"8 + 3 = 11, 11 · 2 = 22"},{"id":"M5B-EKS-S120","side":"120-121","tema":"Algoritmer og programmering","emne":"Tallmønster, tallpyramider og tallmaskiner","q":"En robot ganger først med 6 og deler så på 3. Hva kommer ut når vi putter inn 12?","a":"12 · 6 = 72, 72 : 3 = 24"}],"fakta":[{"side":"6-7","tema":"Geometri og måling","emne":"Vi måler lengder","fakta":["Enheter: mm, cm, dm, m, km","1 m = 10 dm = 100 cm","1 dm = 10 cm = 100 mm","1 cm = 10 mm"]},{"side":"8","tema":"Geometri og måling","emne":"Vi måler lengder","fakta":["Linjestykke: rett strek mellom to punkter (A og B)","Linje: rett strek som fortsetter i begge retninger","Kurve: en strek som kan være buet"]},{"side":"10","tema":"Geometri og måling","emne":"Omkrets","fakta":["Omkrets: lengden rundt en figur"]},{"side":"14","tema":"Geometri og måling","emne":"Areal","fakta":["Areal: størrelsen på en flate","Enheter for areal: kvadratcentimeter (cm²), kvadratmeter (m²), kvadratkilometer (km²)"]},{"side":"17","tema":"Geometri og måling","emne":"Areal","fakta":["1 kvadratcentimeter, cm², er et kvadrat der hver side er 1 cm"]},{"side":"22","tema":"Geometri og måling","emne":"Målestokk","fakta":["Målestokk: når to ting har lik form men ulik størrelse, forteller målestokken hvor mange ganger lengder er forminsket eller forstørret i forhold til virkeligheten","1 : 1 er riktig størrelse, 1 : 2 er forminsket (halv lengde), 2 : 1 er forstørret (dobbel lengde)"]},{"side":"24","tema":"Geometri og måling","emne":"Målestokk","fakta":["Målestokk 1 : 1000: 1 cm på kartet tilsvarer 1000 cm = 10 m i virkeligheten"]},{"side":"25","tema":"Geometri og måling","emne":"Målestokk","fakta":["Målestokk 1 : 50 000: 1 cm på kartet er 50 000 cm = 500 m i virkeligheten","1 km = 1000 m"]},{"side":"42","tema":"Brøk, desimaltall og prosent","emne":"Teller, nevner og likeverdige brøker","fakta":["Teller = antall utvalgte (skraverte) deler. Nevner = antall like deler i alt. Brøkstreken skiller dem."]},{"side":"47","tema":"Brøk, desimaltall og prosent","emne":"Tideler og tallinje","fakta":["Tideler kan skrives både som brøk og som desimaltall. F.eks. 3/10 = 0,3."]},{"side":"48","tema":"Brøk, desimaltall og prosent","emne":"Tideler og tallinje","fakta":["Mellom 0 og 1 på tallinja er det 10 tideler. F.eks. 4/10 = 0,4."]},{"side":"59","tema":"Brøk, desimaltall og prosent","emne":"Prøve og øveside (kap. 6)","fakta":["Brøk er forholdet mellom del og helhet, med teller, brøkstrek og nevner.","Brøker kan være tall på tallinja.","Likeverdige brøker har samme verdi, f.eks. 1/2 = 2/4 = 3/6.","Addisjon: telle hvor mange deler vi har til sammen.","Subtraksjon: ta bort deler."]},{"side":"68","tema":"Tall og regning","emne":"Multiplikasjon","fakta":["Faktor · faktor = produkt. F.eks. 4 · 5 = 20."]},{"side":"90-91","tema":"Tall og regning","emne":"Tekstoppgaver og divisjon med større tall","fakta":["Vi ganger når vi har like grupper, eller har et rutenett.","Ganger vi med et tosifret tall, kan vi dele det opp i tiere og enere: 14 · 6 = 10 · 6 + 4 · 6 = 84.","Vi deler når vi skal fordele noe likt, eller dele i like store deler: 12 : 3 = 4 og 18 : 6 = 3."]},{"side":"96-97","tema":"Tall og regning","emne":"Prøve og øveside (kap. 7)","fakta":["Regneuttrykk med parenteser: regn ut det som står i parentesene først."]},{"side":"98-99","tema":"Geometri og måling","emne":"Forskyvning, speiling og rotasjon","fakta":["Forskyvning: figuren flyttes rett i en retning uten å snus eller dreies.","Speiling: figuren speilvendes om en linje (symmetrilinje).","Rotasjon: figuren dreies rundt et punkt."]},{"side":"104-105","tema":"Algebra og likninger","emne":"Figurrekker og figurtall","fakta":["Figurtall: antall figurdeler følger et mønster som kan beskrives med en tabell."]},{"side":"106-107","tema":"Algebra og likninger","emne":"Figurrekker og figurtall","fakta":["Kvadrattall: figur n er et kvadrat med n ruter på hver side.","Trekanttall: hver figur har én ny rad som er en rute lengre."]},{"side":"110-111","tema":"Algebra og likninger","emne":"Tallfølger og mønster","fakta":["Tallfølge: tall som øker eller minker etter et fast mønster."]},{"side":"114-115","tema":"Tall og regning","emne":"Tallfølger og mønster","fakta":["Tallpyramide: summen av to nabotall skrives i ruta over.","Magisk kvadrat: alle rader, kolonner og diagonaler har lik sum."]},{"side":"119","tema":"Algoritmer og programmering","emne":"Tallmønster, tallpyramider og tallmaskiner","fakta":["Roboten følger en regel for hva den gjør med tallet: her doble og legge til neste tall."]},{"side":"120-121","tema":"Algoritmer og programmering","emne":"Tallmønster, tallpyramider og tallmaskiner","fakta":["Roboter kan gjøre flere regneoperasjoner etter hverandre med samme regel for alle tall."]},{"side":"122","tema":"Algebra og likninger","emne":"Prøve og øveside (kap. 8)","fakta":["Mønstre kan lages med forskyvning, speiling og rotasjon (90° med klokka).","Neste figur i rekke bestemmes av et fast system; figurer kan gjentas eller dreies.","Kvadrattall: like mange ruter bortover som oppover. Trekanttall: nederste rad blir én rute større for hver figur.","Tallfølger øker eller minker etter et fast mønster, f.eks. 1, 4, 7, 10, 13."]},{"side":"126-127","tema":"Algebra og likninger","emne":"Prøve og øveside (kap. 8)","fakta":["Pascals trekant: hvert tall er summen av de to tallene over."]}]};
